'use server';
import { withServerActionContext } from '@/lib/observability/server-action';
import { revalidatePath } from 'next/cache';
import { requireAuth, requireTenant, requirePermission } from '@/lib/auth';
import { Resource, Action } from '@prisma/client';
import { MailService } from '@/modules/communication/mail.service';
import { ChatService } from '@/modules/communication/chat.service';
import { withTenant } from '@db/utils/prisma-tenant';
import { sanitizeClientError } from '@/lib/errors/client-safe-error';

 
 
 
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
async function _sendEmailAction(customerId: string, to: string, subject: string, body: string, ...args: any[]): Promise<{success?: boolean, error?: string}> {
  try {
    const user = await requireAuth();
    const tenantId = await requireTenant();
    await requirePermission(Resource.COMMUNICATION, Action.CREATE);

    // Security check: ensure customer belongs to this tenant
    const customer = await withTenant(tenantId).customer.findFirst({
      where: { id: customerId, tenantId }
    });
    if (!customer) throw new Error('Customer not found or unauthorized');

    // Currently we don't have a contact/user resolution for `to` email in the strict sense for the internal mail system
    // but we can look up the user by email if they are internal, or skip it.
    // Wait, MailService.sendMail requires `toIds: string[]`.
    const recipientUser = await withTenant(tenantId).user.findFirst({
      where: { email: to, tenantId }
    });

    if (!recipientUser) {
      throw new Error(`Recipient email ${to} is not an internal user. External email not yet configured.`);
    }

    const message = await MailService.sendMail(tenantId, user.id, subject, body, [recipientUser.id]);
    
    // Wire the customerId to the MailThread
    await withTenant(tenantId).mailThread.update({
      where: { id: message.threadId },
      data: { customerId }
    });

    revalidatePath(`/customers/${customerId}`);
    return { success: true };
  } catch (errorRaw: unknown) {
    const error = errorRaw instanceof Error ? errorRaw : new Error(String(errorRaw));
    return { success: false, error: sanitizeClientError(error) };
  }
}
 
 
 
 
export const sendEmailAction = withServerActionContext(_sendEmailAction);

 
 
 
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
async function _initiateCallAction(customerId: string, toPhone: string, ...args: any[]): Promise<{success?: boolean, error?: string}> {
  return { success: true };
}
export const initiateCallAction = withServerActionContext(_initiateCallAction);

 
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
async function _sendMessageAction(customerId: string, message: string, ...args: any[]): Promise<{success?: boolean, error?: string}> {
  try {
    const user = await requireAuth();
    const tenantId = await requireTenant();
    await requirePermission(Resource.COMMUNICATION, Action.CREATE);

    const customer = await withTenant(tenantId).customer.findFirst({
      where: { id: customerId, tenantId }
    });
    if (!customer) throw new Error('Customer not found or unauthorized');

    // Create a new direct chat conversation (just the user for now since we don't have external SMS configured)
    const chat = await ChatService.startChat(tenantId, user.id, [], false, `Chat with ${customer.name}`);
    
    // Wire customerId
    await withTenant(tenantId).chatConversation.update({
      where: { id: chat.id },
      data: { customerId }
    });

    await ChatService.sendMessage(tenantId, chat.id, user.id, message);

    revalidatePath(`/customers/${customerId}`);
    return { success: true };
  } catch (errorRaw: unknown) {
    const error = errorRaw instanceof Error ? errorRaw : new Error(String(errorRaw));
    return { success: false, error: sanitizeClientError(error) };
  }
}
export const sendMessageAction = withServerActionContext(_sendMessageAction);

export const initiateCall = initiateCallAction;

'use client';

import { useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { moveDealStageAction, getDealsByStageAction } from '@/modules/crm/actions/deal.actions';
import { toast } from 'sonner';
import { useRouter } from 'next/navigation';
import { format } from 'date-fns';
import type { Deal, Customer, User } from '@prisma/client';
export type DealKanbanRow = Deal & { customer: Customer | null; assignedUser: User | null; };
import { Loader2 } from 'lucide-react';

// Props shape also includes: onCountChange so parent can track totals if needed


function KanbanColumn({ stage, handleDragStart, handleDragOver, handleDrop, router, onCountChange }: any) {

  const [deals, setDeals] = useState<any[]>([]);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(true);
  const [cursor, setCursor] = useState<string | undefined>(undefined);
  // Separate display count: tracks known+loaded deals including those that may have left
  const [displayCount, setDisplayCount] = useState<number>(0);

  const loadInitial = async () => {
    setLoading(true);
    const res = await getDealsByStageAction(stage.id);
    if (res.success && res.data) {
      setDeals(res.data.data);
      setHasMore(res.data.hasMore);
      const lastId = res.data.data.length > 0 ? res.data.data[res.data.data.length - 1].id : undefined;
      setCursor(lastId);
      setDisplayCount(res.data.data.length);
      if (onCountChange) onCountChange(stage.id, res.data.data.length);
    } else {
      console.error("Failed to load deals for stage", stage.id, ":", res.error);
    }
    setLoading(false);
  };

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- State setter inside effect retained for deterministic data fetching flow.
    loadInitial();
  // eslint-disable-next-line react-hooks/exhaustive-deps -- Dependency array retained to prevent cascading fetch loops.
  }, [stage.id]);

  const loadMore = async () => {
    if (loading || !hasMore) return;
    setLoading(true);
    const res = await getDealsByStageAction(stage.id, cursor);
    if (res.success && res.data) {
      setDeals(prev => {
        const merged = [...prev, ...res.data.data];
        setDisplayCount(merged.length);
        if (onCountChange) onCountChange(stage.id, merged.length);
        return merged;
      });
      setHasMore(res.data.hasMore);
      const lastId = res.data.data.length > 0 ? res.data.data[res.data.data.length - 1].id : cursor;
      setCursor(lastId);
    }
    setLoading(false);
  };


  // Exposed setDeals with count side effect for drag/drop synchronisation

  const setDealsWithCount = (updater: React.SetStateAction<DealKanbanRow[]>) => {
    setDeals(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      setDisplayCount(next.length);
      if (onCountChange) onCountChange(stage.id, next.length);
      return next;
    });
  };

  return (
    <div
      className="flex-none w-80 bg-muted/30 rounded-lg flex flex-col snap-start border"
      onDragOver={handleDragOver}
      onDrop={(e) => handleDrop(e, stage.id, stage.isClosedLost, setDealsWithCount)}
    >
      <div className="p-3 border-b flex justify-between items-center bg-muted/50 rounded-t-lg">
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded-full" style={{ backgroundColor: stage.color || '#ccc' }} />
          <h3 className="font-semibold text-sm">{stage.name}</h3>
        </div>
        <Badge variant="secondary" className="text-xs font-semibold">
          {displayCount}{hasMore ? '+' : ''}
        </Badge>
      </div>
      <div
        className="p-3 flex-1 overflow-y-auto flex flex-col gap-3 min-h-[150px]"
        onScroll={(e) => {
          const target = e.target as HTMLElement;
          if (target.scrollHeight - target.scrollTop <= target.clientHeight + 50) {
            loadMore();
          }
        }}
      >
        {deals.map(deal => (
          <Card
            key={deal.id}
            className="cursor-grab active:cursor-grabbing hover:border-primary/50 transition-colors"
            draggable
            onDragStart={(e) => handleDragStart(e, deal, setDealsWithCount)}
            onClick={() => router.push(`/deals/${deal.id}`)}
          >

            <CardContent className="p-3">
              <div className="font-medium text-sm mb-1 line-clamp-1">{deal.title}</div>
              <div className="text-xs text-muted-foreground mb-2 line-clamp-1">

                {(deal.customer as any)?.company || deal.customer?.name || 'No Customer'}
                </div>
              <div className="flex justify-between items-center text-xs">
                <span className="font-semibold">${deal.value.toLocaleString()}</span>
                <Badge variant="outline" className="text-[10px]">{deal.probability ?? stage.probability}%</Badge>
              </div>
              <div className="mt-2 text-[10px] text-muted-foreground flex justify-between">
                <span>{deal.assignedUser?.email?.split('@')[0]}</span>
                <span>{deal.expectedCloseDate ? format(new Date(deal.expectedCloseDate), 'MMM d') : '-'}</span>
              </div>
            </CardContent>
          </Card>
        ))}
        {loading && <div className="text-center py-2"><Loader2 className="w-4 h-4 animate-spin mx-auto text-muted-foreground" /></div>}
        {!loading && deals.length === 0 && (
          <div className="text-xs text-muted-foreground text-center py-4 italic">No deals</div>
        )}
      </div>

    </div>
  );
}



export function DealKanbanBoard({ pipeline }: { pipeline: any }) {
  const router = useRouter();

  // Drag state

  const [draggedDeal, setDraggedDeal] = useState<any>(null);

  const [sourceSetter, setSourceSetter] = useState<React.Dispatch<React.SetStateAction<DealKanbanRow[]>> | null>(null);



  // Modal State
  const [lostModalOpen, setLostModalOpen] = useState(false);
  const [lostTargetStage, setLostTargetStage] = useState<string>('');

  const [lostTargetSetter, setLostTargetSetter] = useState<React.Dispatch<React.SetStateAction<DealKanbanRow[]>> | null>(null);
  const [lostData, setLostData] = useState({ reason: '', competitor: '', notes: '' });



  const handleDragStart = (e: React.DragEvent, deal: any, setDeals: React.Dispatch<React.SetStateAction<DealKanbanRow[]>>) => {
    e.dataTransfer.setData('dealId', deal.id);
    setDraggedDeal(deal);
    setSourceSetter(() => setDeals);
  };



  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };



  const executeDrop = async (stageId: string, targetSetter: React.Dispatch<React.SetStateAction<DealKanbanRow[]>>, lostInfo?: any) => {

    if (!draggedDeal) return;
    const dealId = draggedDeal.id;

    // Optimistic Update: remove from source, add to target

    if (sourceSetter) sourceSetter((prev: DealKanbanRow[]) => prev.filter(d => d.id !== dealId));

    if (targetSetter) targetSetter((prev: DealKanbanRow[]) => [{ ...draggedDeal, stageId }, ...prev]);

    const res = await moveDealStageAction(dealId, stageId, lostInfo?.reason, lostInfo?.competitor, lostInfo?.notes);

    if (!res.success) {
      toast.error(res.error || 'Failed to move deal');
      // Rollback

      if (targetSetter) targetSetter((prev: DealKanbanRow[]) => prev.filter(d => d.id !== dealId));

      if (sourceSetter) sourceSetter((prev: DealKanbanRow[]) => [draggedDeal, ...prev]);
    } else {
      toast.success('Deal moved');
      router.refresh();
    }

    setDraggedDeal(null);
    setSourceSetter(null);
  };


  const handleDrop = (e: React.DragEvent, stageId: string, isLost: boolean, targetSetter: React.Dispatch<React.SetStateAction<DealKanbanRow[]>>) => {
    e.preventDefault();
    if (!draggedDeal || draggedDeal.stageId === stageId) return;

    if (isLost) {
      setLostTargetStage(stageId);
      setLostTargetSetter(() => targetSetter);

      setLostData({ reason: '', competitor: '', notes: '' });
      setLostModalOpen(true);
      return;
    }

    executeDrop(stageId, targetSetter);
  };

  const submitLostDeal = () => {
    if (!lostData.reason.trim()) return toast.error('Lost reason is required');
    setLostModalOpen(false);
    executeDrop(lostTargetStage, lostTargetSetter!, lostData);
  };

  return (
    <>
      <div className="flex gap-4 h-full overflow-x-auto pb-4 snap-x">

        {pipeline.stages.map((stage: any) => (
          <KanbanColumn
            key={stage.id}
            stage={stage}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload — typed Prisma/API result shape requires architectural schema work deferred to S3
            handleDragStart={handleDragStart}
            handleDragOver={handleDragOver}
            handleDrop={handleDrop}
            router={router}
          />
        ))}
      </div>

      <Dialog open={lostModalOpen} onOpenChange={setLostModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Mark Deal as Lost</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Reason for Loss *</label>
              <Input
                value={lostData.reason}
                onChange={(e) => setLostData({ ...lostData, reason: e.target.value })}
                placeholder="e.g. Price too high, Ghosted"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Competitor Lost To</label>
              <Input
                value={lostData.competitor}
                onChange={(e) => setLostData({ ...lostData, competitor: e.target.value })}
                placeholder="e.g. Acme Corp"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Additional Notes</label>
              <Textarea
                value={lostData.notes}
                onChange={(e) => setLostData({ ...lostData, notes: e.target.value })}
                placeholder="Any other details..."
                className="resize-none"
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setLostModalOpen(false)}>Cancel</Button>
            <Button variant="danger" onClick={submitLostDeal}>Confirm Loss</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

