'use client';

import { Suspense, useEffect, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useSession } from '@/lib/auth/SessionProvider';

export default function AcceptInvitePage() {
  return (
    <Suspense fallback={<div className="min-h-screen flex items-center justify-center bg-[#070B18] text-[#8891B0]">Loading invite...</div>}>
      <AcceptInviteInner />
    </Suspense>
  );
}

function AcceptInviteInner() {
  const { isLoaded, refresh } = useSession();
  const searchParams = useSearchParams();
  const router = useRouter();

  const [status, setStatus] = useState<'initial' | 'processing' | 'success' | 'error'>('initial');
  const [errorMsg, setErrorMsg] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const token = searchParams.get('token');

  useEffect(() => {
    if (!isLoaded) return;
    if (!token) {
      setStatus('error');
      setErrorMsg('No invitation token provided.');
    }
  }, [isLoaded, token]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (password !== confirmPassword) {
      setErrorMsg('Passwords do not match');
      return;
    }
    if (password.length < 8) {
      setErrorMsg('Password must be at least 8 characters');
      return;
    }

    setStatus('processing');
    setErrorMsg('');

    try {
      const res = await fetch('/api/auth/accept-invite', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, password }),
      });

      const data = await res.json();
      if (res.ok) {
        setStatus('success');
        await refresh();
        setTimeout(() => {
          router.push('/dashboard');
        }, 1500);
      } else {
        setStatus('error');
        setErrorMsg(data.error || 'Failed to accept invitation.');
      }
    } catch (err) {
      setStatus('error');
      setErrorMsg('An unexpected error occurred. Please try again.');
    }
  };

  if (!isLoaded || status === 'initial' && !token) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-gray-500">Loading...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full space-y-8 bg-white p-8 rounded-xl shadow-lg border border-gray-100 text-center">
        <h2 className="mt-6 text-3xl font-extrabold text-gray-900">
          Accept Invitation
        </h2>
        
        {status === 'processing' && (
          <div className="mt-2 text-sm text-gray-600">
            <p>Setting up your account...</p>
            <div className="mt-4 flex justify-center">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
            </div>
          </div>
        )}

        {status === 'success' && (
          <div className="mt-2 text-sm text-green-600">
            <p>Invitation accepted successfully!</p>
            <p className="mt-2 text-gray-500">Redirecting to your dashboard...</p>
          </div>
        )}

        {status === 'error' && (
          <div className="mt-2 text-sm text-red-600 bg-red-50 p-4 rounded-md">
            {errorMsg}
          </div>
        )}

        {(status === 'initial' || status === 'error') && token && (
          <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 text-left" htmlFor="password">
                  Create Password
                </label>
                <input
                  id="password"
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="appearance-none rounded-md relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                  placeholder="Password"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 text-left" htmlFor="confirm-password">
                  Confirm Password
                </label>
                <input
                  id="confirm-password"
                  type="password"
                  required
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="appearance-none rounded-md relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                  placeholder="Confirm Password"
                />
              </div>
            </div>
            <button
              type="submit"
              className="group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
            >
              Set Password & Accept
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

import { NextResponse } from 'next/server';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { verifyPassword, verifyDummyPassword } from '@/lib/auth/password';
import { createSession } from '@/lib/auth/session';
import { Logger } from '@/lib/logger/logger';
import { DistributedRateLimiter } from '@/lib/rate-limit/rate-limiter';
import { headers } from 'next/headers';

export async function POST(req: Request) {
  const reqHeaders = await headers();
  const ip = reqHeaders.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown';

  // 1. CSRF Origin Validation (API Route protection)
  const origin = reqHeaders.get('origin');
  const host = reqHeaders.get('host');
  // For production environments, Origin must exactly match our intended Host.
  if (process.env.NODE_ENV === 'production' && origin && host) {
    try {
      const originHost = new URL(origin).host;
      if (originHost !== host) {
        Logger.warn('CSRF Origin mismatch', { origin, host, ip });
        return NextResponse.json({ error: 'Invalid request origin' }, { status: 403 });
      }
    } catch {
      return NextResponse.json({ error: 'Invalid origin format' }, { status: 403 });
    }
  }

  // 2. Global IP Rate Limiting (Abuse Protection)
  const ipLimit = await DistributedRateLimiter.checkLimit('system', 'auth', 'login_ip', 20, 60, ip);
  if (!ipLimit.allowed) {
    await logSecurityEvent('RATE_LIMIT_TRIGGERED', 'HIGH', 'Global IP lockout triggered', ip);
    return NextResponse.json({ error: 'Too many attempts. Please try again later.' }, { status: 429 });
  }

  try {
    const body = await req.json();
    const { email, password } = body;

    if (!email || !password || typeof email !== 'string' || typeof password !== 'string') {
      return NextResponse.json({ error: 'Invalid credentials' }, { status: 401 });
    }

    const normalizedEmail = email.toLowerCase().trim();

    const user = await executeAsSystem(SystemOperation.AUTH_BOOTSTRAP, async (tx) => {
      return tx.user.findFirst({
        where: { email: normalizedEmail },
        select: { id: true, status: true, passwordHash: true, tenantId: true }
      });
    });

    // 3. Account-Level Rate Limiting (Temporary Lockout)
    // 5 attempts per 5 minutes per email
    const emailLimit = await DistributedRateLimiter.checkLimit('system', 'auth', 'login_email', 5, 300, ip, normalizedEmail);
    if (!emailLimit.allowed) {
      await logSecurityEvent('RATE_LIMIT_TRIGGERED', 'MEDIUM', 'Login lockout triggered', ip, user?.id, user?.tenantId);
      return NextResponse.json({ error: 'Account temporarily locked due to too many failed attempts. Please try again later.' }, { status: 429 });
    }

    let isValid = false;
    let timingMitigated = false;

    if (!user || !user.passwordHash) {
      // 4. Timing-Attack Mitigation: Constant-time dummy verification
      await verifyDummyPassword(password);
      timingMitigated = true;
    } else {
      if (user.status !== 'ACTIVE') {
        await verifyDummyPassword(password);
        timingMitigated = true;
      } else {
        isValid = await verifyPassword(password, user.passwordHash);
      }
    }

    if (!isValid) {
      // Intentionally advance the email rate limiter again on failure if needed, 
      // but the initial checkLimit already incremented the counter.
      await logSecurityEvent('FAILED_LOGIN', 'LOW', 'Invalid credentials', ip, user?.id, user?.tenantId);
      return NextResponse.json({ error: 'Invalid credentials' }, { status: 401 });
    }

    // 5. Success Flow
    await createSession(user!.id);
    await logSecurityEvent('SUCCESSFUL_LOGIN', 'INFO', 'Native session established', ip, user!.id, user!.tenantId);

    return NextResponse.json({ success: true });

  } catch (err: unknown) {
    Logger.error('Login error:', err instanceof Error ? err.message : String(err));
    return NextResponse.json({ error: 'Invalid credentials' }, { status: 401 });
  }
}

async function logSecurityEvent(eventType: string, severity: string, source: string, ipAddress: string, userId?: string, tenantId?: string) {
  try {
    await executeAsSystem(SystemOperation.AUTH_BOOTSTRAP, async (tx) => {
      await tx.securityEvent.create({
        data: {
          tenantId: tenantId || 'SYSTEM',
          userId: userId || null,
          eventType: eventType as any,
          severity: severity as any,
          source,
          ipAddress,
          userAgent: 'N/A'
        }
      });
    });
  } catch (err) {
    Logger.error('Failed to log security event', err as Error);
  }
}

import { NextResponse } from 'next/server';
import { revokeCurrentSession } from '@/lib/auth/session';
import { Logger } from '@/lib/logger/logger';
import { getCurrentUserIdentity } from '@/lib/auth';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { headers } from 'next/headers';

export async function POST(req: Request) {
  const reqHeaders = await headers();
  const ip = reqHeaders.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown';

  // 1. CSRF Origin Validation
  const origin = reqHeaders.get('origin');
  const host = reqHeaders.get('host');
  if (process.env.NODE_ENV === 'production' && origin && host) {
    try {
      const originHost = new URL(origin).host;
      if (originHost !== host) {
        Logger.warn('CSRF Origin mismatch on logout', { origin, host, ip });
        return NextResponse.json({ error: 'Invalid request origin' }, { status: 403 });
      }
    } catch {
      return NextResponse.json({ error: 'Invalid origin format' }, { status: 403 });
    }
  }

  try {
    const user = await getCurrentUserIdentity();

    // Revoke server-side AuthSession and delete cookie
    await revokeCurrentSession();

    if (user) {
      // Log the event securely
      await executeAsSystem(SystemOperation.AUTH_BOOTSTRAP, async (tx) => {
        await tx.securityEvent.create({
          data: {
            tenantId: user.tenantId || 'SYSTEM',
            userId: user.id,
            eventType: 'LOGOUT' as any,
            severity: 'INFO' as any,
            source: 'Logout route',
            ipAddress: ip,
            userAgent: reqHeaders.get('user-agent') || 'N/A'
          }
        });
      });
    }

    return NextResponse.json({ success: true });
  } catch (err: unknown) {
    Logger.error('Logout error:', err instanceof Error ? err.message : String(err));
    // Fail safely without exposing internal state
    return NextResponse.json({ error: 'Logout failed' }, { status: 500 });
  }
}

