import { NextResponse } from 'next/server';
import { withApiContext } from '@/lib/observability/context';
import { Logger } from '@/lib/logger/logger';
import { withTenant, withTenantTransaction } from '@db/utils/prisma-tenant';
import prisma from '@db/utils/prisma';
import crypto from 'crypto';
import { inngest } from '@/lib/queue/inngest.client';

const _orig_POST = async function (req: Request) {
  try {
    const signature = req.headers.get('x-webhook-signature');
    if (!signature) {
      return NextResponse.json({ error: 'Missing signature' }, { status: 401 });
    }

    const rawBody = await req.text();
    let payload;
    try {
      payload = JSON.parse(rawBody);
    } catch {
      return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 });
    }

    // Identify tenant safely. If generic webhook cannot, it must be specified in query params.
    const url = new URL(req.url);
    const tenantId = url.searchParams.get('tenantId');
    if (!tenantId) {
      return NextResponse.json({ error: 'Missing tenant mapping' }, { status: 400 });
    }

    const expectedSignature = crypto
      .createHmac('sha256', process.env.WEBHOOK_SECRET || 'default_dev_secret')
      .update(rawBody)
      .digest('hex');

    const isValid = signature.length === expectedSignature.length && 
                    crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSignature));

    if (!isValid) {
      // SECURITY: Log unauthorized attempts to SecurityEvent
      await prisma.$transaction(async (baseTx) => {
        const tx = await withTenantTransaction(baseTx, tenantId);
        await tx.securityEvent.create({
          data: {
            tenantId,
            eventType: 'WEBHOOK_SIGNATURE_FAILURE',
            ipAddress: req.headers.get('x-forwarded-for') || 'unknown',
            userAgent: req.headers.get('user-agent') || 'unknown',
            metadata: { provider: 'GENERIC', eventId: payload.id },
            severity: 'HIGH',
            source: 'API'
          }
        });
      });
      return NextResponse.json({ error: 'Invalid signature' }, { status: 401 });
    }

    // G15 Remediation: Establish authoritative tenant binding
    let authoritativeTenantId = tenantId;

    if (payload.resourceId && payload.resourceType) {
      // Authoritative Resource Ownership: Derive tenant from database directly
      if (payload.resourceType === 'CAMERA') {
        const camera = await prisma.camera.findUnique({ where: { id: payload.resourceId } });
        if (camera) authoritativeTenantId = camera.tenantId;
      } else if (payload.resourceType === 'LEAD') {
        const lead = await prisma.lead.findUnique({ where: { id: payload.resourceId } });
        if (lead) authoritativeTenantId = lead.tenantId;
      }
      
      if (authoritativeTenantId !== tenantId) {
         Logger.warn(`[Webhook] Cross-tenant replay blocked. DB Authoritative Tenant ${authoritativeTenantId} != Query Tenant ${tenantId}`);
         return NextResponse.json({ error: 'Tenant ownership mismatch' }, { status: 403 });
      }
    } else if (payload.tenantId) {
      // Consistency Check if no resource identifier is provided
      if (payload.tenantId !== tenantId) {
         Logger.warn(`[Webhook] Cross-tenant replay blocked. Payload Tenant ${payload.tenantId} != Query Tenant ${tenantId}`);
         return NextResponse.json({ error: 'Tenant mismatch in signed payload' }, { status: 403 });
      }
    }

    // Note: If neither resourceId nor payload.tenantId exist, the global webhook secret 
    // is currently the only tenant binding (relying on ?tenantId=X). This is a known 
    // architectural limitation documented in Phase 9.

    const payloadHash = crypto.createHash('sha256').update(rawBody).digest('hex');
    const eventId = payload.id || crypto.randomUUID();

    // Check for idempotency / replay and create securely
    const existingOrNew = await prisma.$transaction(async (baseTx) => {
      const tx = await withTenantTransaction(baseTx, tenantId);
      const existing = await tx.webhookEvent.findFirst({
        where: { provider: 'GENERIC', eventId }
      });
      if (existing) return { existing: true, event: existing };

      const webhookEvent = await tx.webhookEvent.create({
        data: {
          tenantId,
          provider: 'GENERIC',
          eventId,
          eventType: payload.type || 'unknown',
          payloadHash,
          signatureVerified: true,
          status: 'PENDING'
        }
      });
      return { existing: false, event: webhookEvent };
    });

    if (existingOrNew.existing) {
      return NextResponse.json({ success: true, message: 'Already processed' }, { status: 200 });
    }
    
    const webhookEvent = existingOrNew.event;

    // Dispatch to async queue
    await inngest.send({
      name: 'webhook.ingested',
      data: {
        jobId: `wh-${webhookEvent.id}`,
        tenantId,
        actorType: 'SYSTEM',
        correlationId: webhookEvent.id,
        jobType: 'webhook.ingested',
        payload: { webhookEventId: webhookEvent.id },
        schemaVersion: '1.0'
      }
    });

    return NextResponse.json({ success: true, id: webhookEvent.id }, { status: 202 });
  } catch (error) {
    Logger.error('Webhook ingestion error:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

export const POST = withApiContext(_orig_POST);

import { NextResponse } from 'next/server';
import { withApiContext } from '@/lib/observability/context';
import { Logger } from '../../../../lib/logger/logger';
import crypto from 'crypto';

import { Webhook } from 'svix';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { Prisma } from '@prisma/client';

const _orig_POST = async function (req: Request) {
  try {
    const rawBody = await req.text();
    const signature = req.headers.get('svix-signature');
    const secret = process.env.RESEND_WEBHOOK_SECRET;

    if (!secret || !signature) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    let payload;
    if (process.env.NODE_ENV === 'production' || process.env.NODE_ENV === 'test') {
      try {
        const wh = new Webhook(secret);
         
        payload = wh.verify(rawBody, {
          'svix-id': req.headers.get('svix-id') as string,
          'svix-timestamp': req.headers.get('svix-timestamp') as string,
          'svix-signature': signature,
        }) as any;
      } catch (err) {
        Logger.warn('Invalid Resend Webhook Signature', { ip: req.headers.get('x-forwarded-for') });
        return NextResponse.json({ error: 'Invalid signature' }, { status: 400 });
      }
    } else {
      payload = JSON.parse(rawBody);
    }

    const eventType = payload.type; // email.sent, email.delivered, email.bounced
    const emailId = payload.data?.email_id; // Resend's message ID

    if (!emailId) {
      return NextResponse.json({ error: 'Missing email_id' }, { status: 400 });
    }

    // Securely resolve tenantId and message via executeAsSystem (Authoritative correlation)
    const dbResult = await executeAsSystem(SystemOperation.PLATFORM_CRON, async (tx) => {
      // Find the MailMessage by providerMessageId stored in metadata
      // Prisma JSON filtering for PostgreSQL
      const messages = await tx.mailMessage.findMany({
        where: {
          metadata: {
            path: ['providerMessageId'],
            equals: emailId
          }
        },
        take: 1
      });

      if (messages.length === 0) return null;
      const message = messages[0];

      const statusMap: Record<string, string> = {
        'email.sent': 'SENT',
        'email.delivered': 'DELIVERED',
        'email.bounced': 'BOUNCED',
        'email.complained': 'COMPLAINED',
        'email.failed': 'FAILED'
      };
      const newStatus = statusMap[eventType] || 'UNKNOWN';

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const metadata = (message.metadata as any) || {};
      
      // Idempotency: skip if already processed this status
      if (metadata.status === newStatus && newStatus !== 'UNKNOWN') {
        return { message, updated: false, newStatus };
      }

      const updateData: any = { ...metadata, status: newStatus };

      if (newStatus === 'SENT') updateData.sentAt = new Date().toISOString();
      if (newStatus === 'DELIVERED') updateData.deliveredAt = new Date().toISOString();
      if (newStatus === 'BOUNCED' || newStatus === 'FAILED') {
        updateData.failedAt = new Date().toISOString();
        updateData.bouncedAt = newStatus === 'BOUNCED' ? new Date().toISOString() : undefined;
        updateData.failureReason = payload.data?.reason || 'Unknown failure';
      }

      await tx.mailMessage.update({
        where: { id: message.id },
        data: { metadata: updateData }
      });

      return { message, updated: true, newStatus };
    });

    if (!dbResult) {
      Logger.warn(`Resend webhook received for unknown email_id: ${emailId}`);
      return NextResponse.json({ received: true });
    }

    Logger.info(`Received Resend webhook: ${eventType}`, { tenantId: dbResult.message.tenantId, emailId });

    if (dbResult.updated) {
      Logger.info(`Updated EmailMessage ${emailId} to status ${dbResult.newStatus}`, { tenantId: dbResult.message.tenantId, emailId });

      if (dbResult.newStatus === 'BOUNCED' || dbResult.newStatus === 'COMPLAINED') {
        Logger.warn(`Recipient marked unhealthy due to ${dbResult.newStatus}`, { tenantId: dbResult.message.tenantId, emailId, to: payload.data?.to });
      }
    }

    return NextResponse.json({ received: true });
  } catch (errRaw: unknown) {
    const err = errRaw instanceof Error ? errRaw : new Error(String(errRaw));
    Logger.error('Resend webhook processing failed', err, { category: 'external_api' });
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

export const POST = withApiContext(_orig_POST);

