export default function SignInPage() {
  const router = useRouter();
  const { refresh } = useSession();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ email, password })
      });

      const data = await res.json();

      if (!res.ok) {
        if (res.status === 429) {
          setError(data.error || 'Too many attempts. Please try again later.');
        } else {
          setError(data.error || 'Invalid credentials');
        }
      } else {
        await refresh();
        router.push('/dashboard');
      }
    } catch (err) {
      setError('An unexpected error occurred.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-[#070B18] text-[#E7EAF5] px-4">
      <div className="w-full max-w-md bg-white/5 rounded-2xl border border-white/10 p-8 shadow-2xl backdrop-blur-md">
        <h2 className="text-3xl font-bold font-display text-white text-center mb-6">Welcome Back</h2>

        {error && (
          <div className="mb-4 p-3 bg-red-500/10 border border-red-500/20 text-red-400 text-sm rounded-lg text-center">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-medium text-gray-400 mb-1">Email address</label>
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-2.5 text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50"
              placeholder="you@example.com"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-400 mb-1">Password</label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-2.5 text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50"
              placeholder="••••••••"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-blue-600 hover:bg-blue-500 text-white font-semibold py-2.5 rounded-lg transition-colors disabled:opacity-50 mt-2"
          >
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>

        <p className="mt-6 text-center text-sm text-gray-400">
          Don't have an account?{' '}
          <Link href="/sign-up" className="text-blue-400 hover:text-blue-300 transition-colors">
            Contact Admin
          </Link>
        </p>
      </div>
    </div>
  );
}

import { Action, Resource, Prisma } from '@prisma/client';
import { Logger } from '@/lib/observability/logger';
import { headers } from 'next/headers';
import jwt from 'jsonwebtoken';
import { redis } from '@/lib/cache/redis.client';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { setTenantContext } from '@/lib/observability/context';

import { cache } from 'react';

const logger = new Logger();

// AuthUser: the strict Prisma payload type returned by every authenticated DB lookup.
// Defined here so getCurrentUser, requireAuth, and callers share a single source of truth.
export type AuthUser = Prisma.UserGetPayload<{
  include: {
    tenant: true;
    userRoles: {
      include: {
        role: {
          include: {
            permissions: {
              include: { permission: true };
            };
          };
        };
      };
    };
  };
}>;

// The common DB include needed for full user context is inlined below to preserve Prisma type inference.

/**
 * STAGING-ONLY LOAD-TEST IDENTITY BRIDGE
 *
 * Resolves an identity from a cryptographically signed x-load-test-token.
 * ONLY active when:
 *   - NODE_ENV !== 'production'
 *   - CRM_LOAD_TEST_AUTH_ENABLED === 'true'
 *   - LOAD_TEST_SECRET is set
 *   - Token passes full JWT verification (signature, audience, purpose, expiry)
 *   - Resolved user is an explicitly provisioned AUDIT_ user
 *
 * Tenant is ALWAYS resolved from the database; never from token claims.
 * Returns null on any verification failure (falls through to normal Clerk auth).
 */
function isLoadTestAuthEnabled(): boolean {
  console.log('[AUTH] NODE_ENV:', process.env.NODE_ENV);
  console.log('[AUTH] CRM_LOAD_TEST_AUTH_ENABLED:', process.env.CRM_LOAD_TEST_AUTH_ENABLED);
  if (process.env.NODE_ENV === 'production' || process.env.VERCEL_ENV === 'production') return false;
  if (process.env.CRM_LOAD_TEST_AUTH_ENABLED?.trim() !== 'true') return false;
  if (!process.env.LOAD_TEST_SECRET) return false;
  return true;
}

async function tryLoadTestIdentity() {
  // Triple-gate: all conditions must pass or we immediately return null
  if (!isLoadTestAuthEnabled()) return null;
  const secret = process.env.LOAD_TEST_SECRET?.trim() as string;

  let token: string | null = null;
  try {
    const reqHeaders = await headers();
    token = reqHeaders.get('x-load-test-token');
  } catch {
    return null;
  }
  if (!token) return null;

  let decoded: jwt.JwtPayload;
  try {
    const raw = jwt.verify(token, secret, {
      audience: 'crm-staging-load-test',
      issuer: 'crm-phase26-runner',
      algorithms: ['HS256'],
    });
    if (typeof raw === 'string') return null;
    decoded = raw;
  } catch (err: unknown) {
    const errObj = err as Error;
    console.log('[AUTH DEBUG] LOAD_TEST_SECRET length is:', secret.length, 'ends with:', secret.substring(secret.length - 3));
    logger.error('Load-test token verification failed', undefined, { reason: errObj?.name, message: errObj?.message });
    return null;
  }

  // Validate required purpose claim
  if (decoded['purpose'] !== 'crm-phase26-load-test') return null;

  // Extract only the subject (userId)
  const userId = decoded['sub'];
  if (!userId || typeof userId !== 'string') return null;

  // Resolve the user from DB — tenant comes from DB, never from token
  const user = await executeAsSystem(SystemOperation.AUTH_BOOTSTRAP, async (tx) => {
    return tx.user.findUnique({
      where: { id: userId },
      include: {
        tenant: true,
        userRoles: {
          include: { role: { include: { permissions: { include: { permission: true } } } } }
        }
      }
    });
  });

  if (!user) {
    logger.error('Load-test token rejected: user not found in DB', undefined, { userId });
    return null;
  }

  // Enforce: only explicitly provisioned AUDIT_ users may use this path
  if (!user.email.startsWith('audit-load-') && !user.email.includes('AUDIT_LOAD')) {
    logger.error('Load-test token rejected: non-audit user attempted load-test auth', undefined, { userId: '[REDACTED]' });
    return null;
  }

  logger.info('Load-test token accepted', { userId });
  return user;
}

export const getCurrentUser = cache(async function getCurrentUser(): Promise<AuthUser | null> {
  // STAGING-ONLY: Load-test identity bridge (never active in production)
  const loadTestUser = await tryLoadTestIdentity();
  if (loadTestUser) return loadTestUser;

  const { resolveSession } = await import('@/lib/auth/session');
  
  try {
    const nativeIdentity = await resolveSession();
    if (nativeIdentity) {
      if (redis) {
        // Cache could be maintained, but session resolution is fast and DB cached if pooler used.
        // We'll skip setting it in redis for now to keep it completely native-session truth.
      }
      return nativeIdentity;
    }
  } catch (error) {
    if (
      error instanceof Error &&
      (error.message.includes('Dynamic server usage') ||
       (error as any).digest?.startsWith('DYNAMIC_SERVER_USAGE') ||
       (error as any).digest?.startsWith('NEXT_REDIRECT') ||
       (error as any).digest?.startsWith('NEXT_NOT_FOUND'))
    ) {
      throw error;
    }
    logger.error('Native session resolution failed', undefined, { errorMessage: (error as Error).message });
  }

  return null;
});

export async function invalidateUserCache(userId: string) {
  if (redis) {
    await redis.del(`user:${userId}`);
  }
}

export async function getCurrentTenant() {
  const user = await getCurrentUser();
  if (!user || !user.tenantId) {
    return null;
  }
  
  return user.tenant;
}

export async function checkPermission(resource: Resource, action: Action) {
  const user = await getCurrentUser();
  if (!user) return false;

  for (const userRole of user.userRoles) {
    if (userRole.role.name === 'TENANT_ADMIN' || userRole.role.name === 'GLOBAL_ADMIN') {
      return true;
    }

    const hasPermission = userRole.role.permissions.some(
      (rp: { permission: { resource: string; action: string } }) => rp.permission.resource === resource && rp.permission.action === action
    );

    if (hasPermission) return true;
  }

  return false;
}


export async function requireAuth(): Promise<AuthUser> {
  const user = await getCurrentUser();
  
  if (!user) {
    // NOTE: Throw an Error — do NOT redirect here.
    // requireAuth() is called from API routes, Server Actions, AND Server Component layouts.
    // API routes catch this error and return HTTP 401.
    // Server Component layouts (e.g. (crm)/layout.tsx) handle redirect to /sign-in explicitly.
    throw new Error('Unauthorized');
  }

  if (user.status === 'INACTIVE') {
    throw new Error('Unauthorized');
  }

  return user;
}

export async function requireTenant() {

  const tenant = await getCurrentTenant();
  if (!tenant) {
    throw new Error('Tenant Context Missing');
  }
  if (tenant.status !== 'ACTIVE') {
    throw new Error('Forbidden: Tenant is not ACTIVE');
  }
  
  setTenantContext(tenant.id);
  
  return tenant.id;
}

export async function requirePermission(resource: Resource, action: Action) {
  // removed test bypass
  const hasPermission = await checkPermission(resource, action);
  if (!hasPermission) {
    throw new Error(`Forbidden: Requires ${action} on ${resource}`);
  }
  return true;
}

// ============================================================================
// PHASE 26E: LIGHTWEIGHT IDENTITY RESOLUTION FOR HIGH-THROUGHPUT READ PATHS
// ============================================================================

export async function checkPermissionFast(userId: string, resource: Resource, action: Action): Promise<boolean> {
  // Query only what we need to determine if the user has the permission or is an admin.
  // We use executeAsSystem here because reading UserRole and RolePermission requires 
  // system privileges when no tenant context is yet active (RLS would otherwise block it).
  const userRoles = await executeAsSystem(SystemOperation.AUTH_BOOTSTRAP, async (tx) => {
    return tx.userRole.findMany({
      where: { userId },
      include: {
        role: {
          include: {
            permissions: {
              include: { permission: true }
            }
          }
        }
      }
    });
  });

  // Debug-level permission tracing — routed through Logger so it respects LOG_LEVEL and redaction
  // import is lazy to avoid circular-dep risk at module load time

  for (const userRole of userRoles) {
    if (userRole.role.name === 'TENANT_ADMIN' || userRole.role.name === 'GLOBAL_ADMIN') {
      return true;
    }
    const hasPermission = userRole.role.permissions.some(
      (rp) => rp.permission.resource === resource && rp.permission.action === action
    );
    if (hasPermission) return true;
  }
  return false;
}

export async function requirePermissionFast(userId: string, resource: Resource, action: Action) {
  const hasPermission = await checkPermissionFast(userId, resource, action);
  if (!hasPermission) {
    throw new Error(`Forbidden: Requires ${action} on ${resource}`);
  }
  return true;
}

async function tryLoadTestIdentityLight() {
  if (!isLoadTestAuthEnabled()) return null;
  const secret = process.env.LOAD_TEST_SECRET?.trim() as string;

  let token: string | null = null;
  try {
    const reqHeaders = await headers();
    token = reqHeaders.get('x-load-test-token');
  } catch {
    return null;
  }
  if (!token) return null;

  let decoded: jwt.JwtPayload;
  try {
    const raw = jwt.verify(token, secret, {
      audience: 'crm-staging-load-test',
      issuer: 'crm-phase26-runner',
      algorithms: ['HS256'],
    });
    if (typeof raw === 'string') return null;
    decoded = raw;
  } catch (err: unknown) {
    const errObj = err as Error;
    logger.error('Load-test token verification failed', undefined, { reason: errObj?.name, message: errObj?.message, secretSuffix: secret.substring(secret.length - 5) });
    return null;
  }

  if (decoded['purpose'] !== 'crm-phase26-load-test') return null;

  const userId = decoded['sub'];
  if (!userId || typeof userId !== 'string') return null;

  // SHALLOW LOOKUP: No roles, no permissions, no related tenant object.
  const user = await executeAsSystem(SystemOperation.AUTH_BOOTSTRAP, async (tx) => {
    return tx.user.findUnique({
      where: { id: userId },
      select: { id: true, tenantId: true, email: true, status: true, firstName: true, lastName: true }
    });
  });

  if (!user) return null;

  if (!user.email.startsWith('audit-load-') && !user.email.includes('AUDIT_LOAD')) {
    logger.error('Load-test token rejected: non-audit user attempted load-test auth', undefined, { userId: '[REDACTED]' });
    return null;
  }

  return user;
}

export const getCurrentUserIdentity = cache(async function getCurrentUserIdentity() {
  const loadTestUser = await tryLoadTestIdentityLight();
  if (loadTestUser) return loadTestUser;

  const { resolveSession } = await import('@/lib/auth/session');
  
  const nativeIdentity = await resolveSession();
  if (nativeIdentity) {
    return nativeIdentity; // Native Session is Authoritative
  }

  return null;
});

export async function requireAuthIdentity() {
  const user = await getCurrentUserIdentity();
  if (!user) {
    throw new Error('Unauthorized');
  }

  if (user.status === 'INACTIVE') {
    throw new Error('Unauthorized');
  }

  return user;
}

export function requireTenantFromIdentity(user: { tenantId: string | null }) {

  if (!user || !user.tenantId) {
    throw new Error('Tenant Context Missing');
  }
  return user.tenantId;
}

"use client";

import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';

export type NativeSessionUser = {
  id: string;
  tenantId: string;
  status: string;
  email: string;
  firstName: string | null;
  lastName: string | null;
};

type SessionState = {
  isLoaded: boolean;
  isAuthenticated: boolean;
  user: NativeSessionUser | null;
  refresh: () => Promise<void>;
};

const SessionContext = createContext<SessionState | undefined>(undefined);

export function SessionProvider({ children }: { children: React.ReactNode }) {
  const [isLoaded, setIsLoaded] = useState(false);
  const [user, setUser] = useState<NativeSessionUser | null>(null);

  const fetchSession = useCallback(async () => {
    try {
      const response = await fetch('/api/auth/me', {
        headers: {
          'Content-Type': 'application/json'
        },
        // Force no-cache so we always hit the server (which reads the HttpOnly cookie)
        cache: 'no-store'
      });
      if (response.ok) {
        const userData = await response.json();
        setUser(userData);
      } else {
        setUser(null);
      }
    } catch (err) {
      console.error('Failed to fetch session', err);
      setUser(null);
    } finally {
      setIsLoaded(true);
    }
  }, []);

  useEffect(() => {
    fetchSession();
  }, [fetchSession]);

  return (
    <SessionContext.Provider value={{
      isLoaded,
      isAuthenticated: !!user,
      user,
      refresh: fetchSession
    }}>
      {children}
    </SessionContext.Provider>
  );
}

export function useSession() {
  const context = useContext(SessionContext);
  if (context === undefined) {
    throw new Error('useSession must be used within a SessionProvider');
  }
  return context;
}

import * as argon2 from 'argon2';

/**
 * Hash a password using Argon2id with memory-hard settings suitable for our environment.
 */
export async function hashPassword(password: string): Promise<string> {
  return await argon2.hash(password, {
    type: argon2.argon2id,
    memoryCost: 65536, // 64MB memory per hash
    timeCost: 3,       // 3 iterations
    parallelism: 4,    // 4 threads
  });
}

export async function verifyPassword(password: string, hash: string): Promise<boolean> {
  try {
    return await argon2.verify(hash, password);
  } catch (error) {
    // Treat malformed hashes or other errors as a failed verification
    return false;
  }
}

// A pre-computed dummy Argon2id hash for timing-attack mitigation.
// This represents the hash of a securely generated, unknown random password.
// DO NOT use this for any real user.
const DUMMY_HASH = '$argon2id$v=19$m=65536,t=3,p=4$c29tZXNhbHRzdHJpbmc$G+E3/X4n0b2sR+D3M8N/H0fF2Q6vQ6g5A8Z8E2tQ0pQ';

/**
 * Performs a dummy password verification to mitigate user-enumeration timing attacks.
 * This ensures that login attempts for non-existent users take a comparable amount 
 * of time to login attempts for real users.
 */
export async function verifyDummyPassword(password: string): Promise<boolean> {
  try {
    // We verify against the constant dummy hash. This will predictably take
    // approximately the same time as a real Argon2id verify call.
    // It will essentially always return false (unless the user guesses the dummy password,
    // which is random and not associated with any account anyway).
    await argon2.verify(DUMMY_HASH, password);
    return false;
  } catch (error) {
    return false;
  }
}

import { GoogleGenAI } from '@google/genai';
import { AIEngineProvider, AISession, AITurnContext, AIToolResult, AITurnResult } from './ai-provider.interface';
import { AIContext } from '@/modules/ai/context/context-builder.service';
import { Logger } from '../../logger/logger';
import { AIConfig } from '../../config/ai.config';
import { ProviderRateLimitError, ProviderTransientError, ProviderPermanentError, ProviderConfigurationError } from '../../observability/errors';

export class GeminiEngineProvider implements AIEngineProvider {
  private ai?: GoogleGenAI;
  private modelName: string;
  private isConfigured: boolean;

  constructor() {
    const apiKey = process.env.GEMINI_API_KEY;
    this.isConfigured = !!apiKey;
    if (this.isConfigured) {
      this.ai = new GoogleGenAI({ apiKey: apiKey! });
    }
    this.modelName = process.env.AI_MODEL || 'gemini-3.5-flash';
  }

  createSession(aiContext: AIContext): AISession {
    if (!this.ai) {
      throw new Error('GeminiProvider is unavailable: GEMINI_API_KEY is missing.');
    }

    Object.freeze(aiContext);

    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
    let chat: any = null;
    const aiClient = this.ai;
    const model = this.modelName;
 
 


    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
    const sendMessageWithRetry = async (payload: any, requestId?: string): Promise<any> => {
      let attempt = 0;
      while (true) {
        try {
          return await chat.sendMessage(payload);
        } catch (errRaw: unknown) {


          const err = errRaw instanceof Error ? errRaw : new Error(String(errRaw));
          attempt++;
          const msg = err.message || '';

          // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
          const status = (err as any)?.status || (err as any)?.response?.status;

          const isTransient =
            msg.includes('429') ||
            msg.includes('500') ||
            msg.includes('502') ||
            msg.includes('503') ||
            msg.includes('504') ||
            msg.includes('fetch failed') ||
            msg.includes('network') ||
            status === 429 ||
            status >= 500;

          if (!isTransient || attempt > AIConfig.GEMINI_MAX_RETRIES) {
            throw err;
          }

          let backoff = Math.min(AIConfig.GEMINI_MAX_BACKOFF_MS, AIConfig.GEMINI_INITIAL_BACKOFF_MS * Math.pow(2, attempt - 1));
          backoff += Math.floor(Math.random() * 200);

          Logger.warn('AI Retry', { event: 'AI_RETRY', requestId, attempt, maxAttempts: AIConfig.GEMINI_MAX_RETRIES, delayMs: backoff });
          await new Promise(resolve => setTimeout(resolve, backoff));
        }
      }
    };

    return {
      async processTurn(context: AITurnContext): Promise<AITurnResult> {
        const geminiTools = context.tools.length > 0 ? [{
          functionDeclarations: context.tools.map(tool => ({
            name: tool.name,
            description: tool.description,
            parameters: tool.parameters || { type: 'OBJECT', properties: {} }
          }))
        }] : undefined;

        let geminiHistory;
        if (context.history && context.history.length > 0) {
          geminiHistory = context.history.map(h => ({
            role: h.role === 'assistant' || h.role === 'tool' ? 'model' : 'user',
            parts: [{ text: h.content }]
          }));
        }

        // Initialize chat on first turn

        if (!chat) {
          chat = aiClient.chats.create({
            model: model,
            config: {
              systemInstruction: context.systemInstruction,
              // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
              tools: geminiTools as any,
              temperature: 0.1,
            },
            history: geminiHistory ?? [],

          });
        }

        const response = await sendMessageWithRetry({ message: context.prompt }, context.requestId);
        
        if (response.functionCalls && response.functionCalls.length > 0) {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
          const toolRequests = response.functionCalls.map((fc: any, index: number) => ({
            id: `call_${Date.now()}_${index}`,
            name: fc.name,
            args: fc.args || {}
          }));
          return { toolRequests };
        }

        return { text: response.text || '' };

      },

      async submitToolResults(results: AIToolResult[]): Promise<AITurnResult> {
        const functionResponses = results.map(res => {
           let resultStr = '';

           try {
             resultStr = JSON.stringify(res.result);
           // eslint-disable-next-line @typescript-eslint/no-unused-vars -- Intentional callback/interface parameter
           } catch(e) {

             resultStr = String(res.result);
           }
           if (resultStr.length > AIConfig.MAX_TOOL_RESULT_BYTES) {

              return { 
                // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
                name: (res as any).name || 'unknown', 

                response: { truncated: true, reason: 'RESULT_SIZE_LIMIT' } 
              };
           }
           // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
           return { name: (res as any).name, response: res.result };
        });

        // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
        const response = await sendMessageWithRetry({ message: functionResponses } as any);
        
        if (response.functionCalls && response.functionCalls.length > 0) {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
          const toolRequests = response.functionCalls.map((fc: any, index: number) => ({
            id: `call_${Date.now()}_${index}`,
            name: fc.name,
            args: fc.args || {}
          }));
          return { toolRequests };
        }

        return { text: response.text || '' };
      }
    };
  }
}

import { PDFDocument, rgb, StandardFonts } from 'pdf-lib';
import { DocumentProvider, QuoteSnapshot } from './document-provider.factory';

export class PdfGeneratorProvider implements DocumentProvider {
  async generateQuoteDocument(snapshot: QuoteSnapshot): Promise<Uint8Array> {
    const pdfDoc = await PDFDocument.create();
    const timesRomanFont = await pdfDoc.embedFont(StandardFonts.TimesRoman);
    const timesRomanBold = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);

    const page = pdfDoc.addPage([595.28, 841.89]); // A4
    const { width, height } = page.getSize();
    const margin = 50;

    let cursorY = height - margin;

    // Header
    page.drawText(`Quotation: ${snapshot.quote.id}`, {
      x: margin,
      y: cursorY,
      size: 18,
      font: timesRomanBold,
      color: rgb(0, 0, 0),
    });
    cursorY -= 30;

    // Company & Customer
    page.drawText(`Tenant: ${snapshot.tenant.name}`, { x: margin, y: cursorY, size: 12, font: timesRomanFont });
    cursorY -= 20;
    page.drawText(`Customer: ${snapshot.customer.name}`, { x: margin, y: cursorY, size: 12, font: timesRomanFont });
    cursorY -= 40;

    // Table Header
    page.drawText('Item', { x: margin, y: cursorY, size: 12, font: timesRomanBold });
    page.drawText('Qty', { x: margin + 200, y: cursorY, size: 12, font: timesRomanBold });
    page.drawText('Unit Price', { x: margin + 250, y: cursorY, size: 12, font: timesRomanBold });
    page.drawText('Discount %', { x: margin + 350, y: cursorY, size: 12, font: timesRomanBold });
    page.drawText('Subtotal', { x: margin + 450, y: cursorY, size: 12, font: timesRomanBold });
    cursorY -= 20;

    // Items
    for (const item of snapshot.lineItems) {
      page.drawText(`${item.productId}`, { x: margin, y: cursorY, size: 10, font: timesRomanFont });
      page.drawText(`${item.quantity}`, { x: margin + 200, y: cursorY, size: 10, font: timesRomanFont });
      page.drawText(`$${item.unitPrice.toString()}`, { x: margin + 250, y: cursorY, size: 10, font: timesRomanFont });
      page.drawText(`${item.discount}%`, { x: margin + 350, y: cursorY, size: 10, font: timesRomanFont });
      page.drawText(`$${item.subtotal.toString()}`, { x: margin + 450, y: cursorY, size: 10, font: timesRomanFont });
      cursorY -= 20;
    }

    cursorY -= 20;
    page.drawText(`Subtotal: $${snapshot.quote.subtotal.toString()}`, { x: margin + 350, y: cursorY, size: 12, font: timesRomanBold });
    cursorY -= 20;
    page.drawText(`Discount Total: $${snapshot.quote.discountTotal.toString()}`, { x: margin + 350, y: cursorY, size: 12, font: timesRomanBold });
    cursorY -= 20;
    page.drawText(`Grand Total: $${snapshot.quote.grandTotal.toString()}`, { x: margin + 350, y: cursorY, size: 14, font: timesRomanBold });

    return await pdfDoc.save();
  }
}

