import { inngest } from '../inngest.client';
import { withJobContext } from '../worker';
import { SecureJobEnvelope } from '../types';
import { AIProviderFactory } from '../../providers/ai/ai-provider.factory';
import { CameraEventService } from '@/modules/cctv/camera-event.service';
import { generateSignedDownloadUrl } from '@/lib/providers/storage/s3.provider';
import { Logger } from '@/lib/logger/logger';

export const cctvVisionWorker = inngest.createFunction(
  { 
    id: 'cctv-vision-inference-worker',
    triggers: [{ event: 'cctv.recording.completed' }],
    concurrency: {
      limit: 2, // Heavy AI processing, keep limit tight
      key: 'event.data.tenantId'
    },
    onFailure: async ({ event, error }) => {
      const { getFailureEventIdSafe, sendToDeadLetterQueue } = await import('../worker');
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const safeEvent = event as { data: { event: { data: any, attemptCount?: number } } };
      const originalEvent = safeEvent.data.event;
      const envelope = originalEvent.data;
      if (envelope && envelope.tenantId) {
        const eventId = getFailureEventIdSafe(event);
        await sendToDeadLetterQueue(envelope, new Error(error.message), originalEvent.attemptCount ?? 1, eventId);
      }
    },
  },
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  async ({ event, step }: { event: { data: SecureJobEnvelope<{ recordingId: string }> }, step: any }) => {
    return await step.run('execute-vision-inference', async () => {
      return await withJobContext(event.data, async (tx, payload) => {
        const { recordingId } = payload;

        // 1. Authoritative recording lookup. NEVER trust tenantId from payload for isolation boundary!
        // We look it up in globalPrisma to confirm ownership, and check if camera is decommissioned.
        const recording = await tx.recording.findUnique({
          where: { id: recordingId },
          include: { camera: true }
        });

        if (!recording) {
          Logger.warn('[CCTV Vision] Recording not found, aborting inference', { recordingId });
          return { success: false, reason: 'RECORDING_NOT_FOUND' };
        }

        const authoritativeTenantId = recording.tenantId;

        // If the envelope tenant doesn't match authoritative tenant, alert forged payload!
        if (event.data.tenantId !== authoritativeTenantId) {
          Logger.error('[CCTV Vision] Tenant mismatch detected in job payload! Forgery attempt?', { 
            envelopeTenantId: event.data.tenantId, 
            authoritativeTenantId 
          });
          throw new Error('SECURITY_VIOLATION_TENANT_MISMATCH');
        }

        if (recording.camera.status === 'MAINTENANCE' || recording.camera.deletedAt) {
          Logger.info('[CCTV Vision] Camera is decommissioned, deleted, or in maintenance, skipping AI', { cameraId: recording.camera.id });
          return { success: false, reason: 'CAMERA_INACTIVE' };
        }

        // 2. Idempotency Check: Did we already process this recording?
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const existingEvents = await tx.$queryRaw<any[]>`
          SELECT id FROM "public"."CameraEvent" 
          WHERE "tenantId" = ${authoritativeTenantId} 
            AND "cameraId" = ${recording.cameraId} 
            AND "metadata"->>'recordingId' = ${recordingId}
          LIMIT 1
        `;

        if (existingEvents && existingEvents.length > 0) {
          Logger.info('[CCTV Vision] Idempotency: Recording already processed by AI.', { recordingId });
          return { success: true, alreadyProcessed: true };
        }

        // 3. Prepare VisionInput
        let signedUrl: string;
        try {
          // Short lived URL (e.g., 5 mins)
          signedUrl = await generateSignedDownloadUrl(recording.storageKey, 300);
        } catch (_e) {
          Logger.error('[CCTV Vision] Failed to generate signed URL for recording', { recordingId });
          throw new Error('STORAGE_ACCESS_DENIED');
        }

        // 4. Invoke VisionInferenceProvider
        const provider = AIProviderFactory.getVisionProvider('GEMINI');

        let detections = [];
        try {
          detections = await provider.analyze({
            type: 'URL',
            data: signedUrl,
            mimeType: 'video/mp4' // Assuming mp4 from cctv ingestion daemon
          });
        } catch (error) {
          // If unconfigured, degrade safely without failing job loop repeatedly
          if ((error as Error).message === 'AI_PROVIDER_NOT_CONFIGURED') {
            Logger.info('[CCTV Vision] Provider unconfigured. Degrading gracefully.', { recordingId });
            return { success: false, reason: 'AI_PROVIDER_NOT_CONFIGURED' };
          }
          throw error;
        }

        // 5. Validation and Normalization
        const eventIds = await CameraEventService.processVisionDetections(
          authoritativeTenantId,
          recording.cameraId,
          detections,
          0.65 // Confidence threshold
        );

        // Optionally, attach recordingId to the metadata of the events to guarantee idempotency links
        if (eventIds.length > 0) {
          await tx.cameraEvent.updateMany({
            where: { id: { in: eventIds }, tenantId: authoritativeTenantId },
            data: {
              metadata: { recordingId: recordingId, source: 'VISION_INFERENCE' }
            }
          });
        }

        return { success: true, detectionsProcessed: detections.length, eventsCreated: eventIds.length };
      });
    });
  }
);

import { inngest } from '../inngest.client';
import { SecureJobEnvelope } from '../types';
import prisma from '@db/utils/prisma';
import { NotificationProviderFactory } from '@/infrastructure/notification/notification.factory';
import { Logger } from '@/lib/logger/logger';
import { withIdempotency, IdempotencyOperations } from '@/lib/idempotency';

export const notificationWorker = inngest.createFunction(
  { 
    id: 'notification-send-worker',
    triggers: [{ event: 'NOTIFICATION_SEND' }],
    concurrency: {
      limit: 10,
      key: 'event.data.tenantId' // Prevent API limits from being exhausted by a single tenant
    },
    onFailure: async ({ event, error }) => {
      const { getFailureEventIdSafe, sendToDeadLetterQueue } = await import('../worker');
      const safeEvent = event as { data: { event: { data: unknown, attemptCount?: number } } };
      const originalEvent = safeEvent.data.event;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const envelope = originalEvent.data as SecureJobEnvelope<any>;
      if (envelope && envelope.tenantId) {
        const eventId = getFailureEventIdSafe(event);
        await sendToDeadLetterQueue(envelope, new Error(error.message), originalEvent.attemptCount ?? 1, eventId);
      }
    }
  },
  async ({ event, step }) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const payload = event.data.payload as any;
    const tenantId = event.data.tenantId;

    // STEP 1: Idempotent Database Write
    const _notification = await step.run('create-notification-db', async () => {
      // Use DB-level idempotency to guarantee duplicate worker executions cannot create duplicate notifications
      return await withIdempotency(
        tenantId,
        'SYSTEM', // System actor
        IdempotencyOperations.SEND_NOTIFICATION,
        event.data.jobId, // The UUID assigned to the EventOutbox transactionally
        payload,
        async (tx) => {
          // Security: Verify user belongs to tenant (N2, N4, N5)
          const targetUser = await tx.user.findFirst({
            where: { id: payload.userId, tenantId: payload.tenantId, deletedAt: null }
          });
          if (!targetUser) {
            throw new Error(`403: Target user does not belong to tenant or is deactivated`);
          }

          return await tx.notification.create({
            data: {
              tenantId: payload.tenantId,
              userId: payload.userId,
              type: payload.type,
              title: payload.title,
              body: payload.body,
              actionUrl: payload.actionUrl
            }
          });
        },
        async (tId, uId, rId) => {
          return await prisma.notification.findUnique({ where: { id: rId } });
        }
      );
    });

    // STEP 2: Best-Effort Realtime Delivery
    await step.run('deliver-realtime', async () => {
      const provider = NotificationProviderFactory.getNotificationProvider();

      try {
        await provider.send({
          tenantId: payload.tenantId,
          userId: payload.userId,
          title: payload.title,
          body: payload.body,
          type: payload.type,
          actionUrl: payload.actionUrl
        });
      } catch (err: any) {
        // Realtime Delivery Semantics (Phase 8):
        // 1. The DB write (Step 1) is strictly durable and guaranteed.
        // 2. Realtime provider is best-effort. If it fails transiently, we swallow the error 
        //    because we do NOT want Inngest to retry the entire job (which would re-run DB insert logic).
        // 3. We distinguish permanent configuration errors vs transient network issues via logging.
        const errorMessage = err?.message || 'Unknown error';
        if (errorMessage.includes('credentials') || errorMessage.includes('Unauthorized')) {
           Logger.error('Realtime provider configuration error (Permanent)', { error: errorMessage, tenantId, userId: payload.userId });
           // Swallow error to reach terminal success state (DB already saved).
        } else {
           Logger.warn('Realtime delivery transient failure (Best Effort)', { error: errorMessage, tenantId, userId: payload.userId });
           // Swallow transient errors. The user will see the notification on next page load.
        }
      }
    });
  }
);

import { inngest } from '../inngest.client';
import { withJobContext } from '../worker';
import { SecureJobEnvelope } from '../types';
import { EventBus } from '@/modules/core/events/event-bus';

export const outboxWorker = inngest.createFunction(
  { 
    id: 'outbox-worker',
    triggers: [{ event: 'outbox.process' }],
    concurrency: {
      limit: 10,
      key: 'event.data.tenantId' 
    },
    retries: 3,
    onFailure: async ({ event, error }) => {
      const { getFailureEventIdSafe, sendToDeadLetterQueue } = await import('../worker');
       
      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
      const safeEvent = event as { data: { event: { data: any, attemptCount?: number } } };
      const originalEvent = safeEvent.data.event;
      const envelope = originalEvent.data;
      if (envelope && envelope.tenantId) {
        const eventId = getFailureEventIdSafe(event);
        await sendToDeadLetterQueue(envelope, new Error(error.message), originalEvent.attemptCount ?? 1, eventId);
      }
    },
   
  },
  outboxWorkerHandler
);

export async function outboxWorkerHandler({ event, step }: { event: { data: SecureJobEnvelope<any> }, step: any }) {
    return await step.run('process-outbox-event', async () => {
      
      // CALL_COMPLETED handled outside transaction due to long-running AI API calls
      if (event.data.jobType === 'CALL_COMPLETED') {
        const { processCallCompleted } = await import('@/modules/communication/jobs/call-transcription.worker');
        return await processCallCompleted(event.data);
      }

      // Decouple Provider Network Calls from DB Transaction
      if (event.data.jobType === 'SEND_EMAIL') {
        const idempotencyKey = event.data.jobId;
        const emailPayload = {
          ...event.data.payload,
          headers: { ...(event.data.payload as any).headers, 'Idempotency-Key': idempotencyKey }
        };

        // 1. Authorize & Establish State (In Transaction)
        await step.run('authorize-and-record-email', async () => {
          return await withJobContext(event.data, async (_tx) => {
            return { success: true };
          });
        });

        // 2. Deliver via Provider (Outside Transaction)
        const result = await step.run('deliver-email', async () => {
          const { ProviderFactory } = await import('@/lib/providers/provider.factory');
          const provider = ProviderFactory.getEmailProvider();
          return await provider.sendEmail(event.data.tenantId, emailPayload);
        });

        if (!result.success) {
          const { Logger } = await import('@/lib/logger/logger');
          const { ProviderPermanentError, ProviderTransientError, ProviderConfigurationError } = await import('@/lib/observability/errors');
          const errorMsg = result.error || 'Unknown error';
          let errObj: Error;
          let isPermanent = false;
          if (errorMsg.includes('not configured')) {
            errObj = new ProviderConfigurationError(`Email not configured: ${errorMsg}`);
            isPermanent = true;
          } else if (errorMsg.includes('invalid_email') || errorMsg.includes('rejected') || errorMsg.includes('not_found')) {
            errObj = new ProviderPermanentError(`Permanent email failure: ${errorMsg}`);
            isPermanent = true;
          } else {
            errObj = new ProviderTransientError(`Transient email failure: ${errorMsg}`);
          }
          if (isPermanent) {
            Logger.error('Email Provider failed permanently', errObj, { jobId: event.data.jobId });
            const { NonRetriableError } = await import('inngest');
            throw new NonRetriableError(errObj.message);
          }
          Logger.warn('Email Provider failed transiently', errObj, { jobId: event.data.jobId });
          throw errObj;
        }
        return { success: true };
      }

      if (event.data.jobType === 'SEND_SMS') {
        const idempotencyKey = event.data.jobId;
        
        await step.run('authorize-and-record-sms', async () => {
          return await withJobContext(event.data, async (_tx) => {
            return { success: true };
          });
        });

        const result = await step.run('deliver-sms', async () => {
          const { ProviderFactory } = await import('@/lib/providers/provider.factory');
          const provider = ProviderFactory.getTelephonyProvider();
          return await provider.sendSms(event.data.tenantId, {
            ...(event.data.payload as any),
            idempotencyKey
          });
        });

        if (!result.success) {
          const { Logger } = await import('@/lib/logger/logger');
          const { ProviderPermanentError, ProviderTransientError, ProviderConfigurationError } = await import('@/lib/observability/errors');
          const errorMsg = result.error || 'Unknown error';
          let errObj: Error;
          let isPermanent = false;
          if (errorMsg.includes('not configured')) {
            errObj = new ProviderConfigurationError(`SMS not configured: ${errorMsg}`);
            isPermanent = true;
          } else if (errorMsg.includes('unregistered') || errorMsg.includes('invalid_number')) {
            errObj = new ProviderPermanentError(`Permanent SMS failure: ${errorMsg}`);
            isPermanent = true;
          } else {
            errObj = new ProviderTransientError(`Transient SMS failure: ${errorMsg}`);
          }
          if (isPermanent) {
            Logger.error('SMS Provider failed permanently', errObj, { jobId: event.data.jobId });
            const { NonRetriableError } = await import('inngest');
            throw new NonRetriableError(errObj.message);
          }
          Logger.warn('SMS Provider failed transiently', errObj, { jobId: event.data.jobId });
          throw errObj;
        }
        return { success: true };
      }

      if (event.data.jobType === 'MAKE_CALL') {
        const idempotencyKey = event.data.jobId;

        await step.run('authorize-and-record-call', async () => {
          return await withJobContext(event.data, async (_tx) => {
            return { success: true };
          });
        });

        const result = await step.run('deliver-call', async () => {
          const { ProviderFactory } = await import('@/lib/providers/provider.factory');
          const provider = ProviderFactory.getTelephonyProvider();
          return await provider.initiateCall(event.data.tenantId, {
            ...(event.data.payload as any),
            idempotencyKey
          });
        });

        if (!result.success) {
          const { Logger } = await import('@/lib/logger/logger');
          const { ProviderPermanentError, ProviderTransientError, ProviderConfigurationError } = await import('@/lib/observability/errors');
          const errorMsg = result.error || 'Unknown error';
          let errObj: Error;
          let isPermanent = false;
          if (errorMsg.includes('not configured')) {
            errObj = new ProviderConfigurationError(`Telephony not configured: ${errorMsg}`);
            isPermanent = true;
          } else if (errorMsg.includes('unregistered') || errorMsg.includes('invalid_number')) {
            errObj = new ProviderPermanentError(`Permanent Call failure: ${errorMsg}`);
            isPermanent = true;
          } else {
            errObj = new ProviderTransientError(`Transient Call failure: ${errorMsg}`);
          }
          if (isPermanent) {
            Logger.error('Call Provider failed permanently', errObj, { jobId: event.data.jobId });
            const { NonRetriableError } = await import('inngest');
            throw new NonRetriableError(errObj.message);
          }
          Logger.warn('Call Provider failed transiently', errObj, { jobId: event.data.jobId });
          throw errObj;
        }
        return { success: true };
      }

      return await withJobContext(event.data, async (tx, payload) => {
        if (event.data.jobType === 'CCTV.AI_EVENT.DETECTED') {
          const aiEventId = payload.aiEventId;
          const cameraId = payload.cameraId;
          
           
          const camera = await tx.camera.findFirst({ where: { id: cameraId }, include: { location: true } });
          if (!camera) throw new Error("Camera not found");

          // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
          let severity: any = 'LOW';
          const obj = payload.detectedObject.toLowerCase();
          if (obj.includes('person')) {
            severity = 'HIGH';
          } else if (obj.includes('vehicle')) {
            severity = 'MEDIUM';
          } else if (obj.includes('restricted') || obj.includes('intrusion')) {
            severity = 'CRITICAL';
          }

          const title = `Security Alert: ${payload.detectedObject}`;

          if (camera.location) {
            await tx.incident.create({
              data: {
                tenantId: event.data.tenantId,
                locationId: camera.locationId!,
                cameraId: camera.id,
                aiEventId: aiEventId,
                title,
                severity,
                status: 'OPEN',
              }
            });

            await tx.activityTimeline.create({
              data: {
                tenantId: event.data.tenantId,
                type: 'SYSTEM',
                content: `${title} [${severity}] at ${camera.name} (${Math.round(payload.confidence * 100)}% confidence)`,
                actorId: payload.actorId,
                entityType: 'CUSTOMER',
                entityId: camera.location.customerId
              }
            });

            await tx.notification.create({
              data: {
                tenantId: event.data.tenantId,
                userId: payload.actorId,
                type: 'ALERT',
                title: 'Camera AI Event',
                body: 'AI detected a significant event.',
                isRead: false
              }
            });
          }
        } else if (event.data.jobType === 'cctv.recording.completed' || event.data.jobType === 'QUOTE_APPROVED' || event.data.jobType === 'NOTIFICATION_SEND' || event.data.jobType === 'workflow.execute') {
          // Explicitly whitelist and relay events to the distributed Inngest pipeline
          await inngest.send({
            name: event.data.jobType,
            data: {
              ...event.data
            }
          });
        } else {
          // Fallback for other events
          await EventBus.emit(event.data.jobType, {
            tenantId: event.data.tenantId,
            ...(payload as object)
          });
        }
        
        return { success: true };
      });
    });
  }

