        actorId: user.id,
        actorType: 'USER',
        action: 'CAMERA_CREATED',
        resource: 'CUSTOMER', // Mapping to customer due to schema
        resourceId: location.customerId,
        metadata: { cameraId: camera.id, name: camera.name }
