import { inngest } from '@/lib/queue/inngest.client';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { withTenant } from '@db/utils/prisma-tenant';
import { Logger } from '@/lib/logger/logger';

const MAX_RETRIES = 5;

export async function processOutbox() {
  Logger.info('Processing EventOutbox...');

  // Minimum required system bypass to scan pending jobs across all tenants
  const pendingEvents = await executeAsSystem(SystemOperation.PLATFORM_CRON, async (tx) => {
    return tx.eventOutbox.findMany({
      where: {
        status: { in: ['PENDING', 'FAILED'] },
        nextRetryAt: { lte: new Date() },
        retryCount: { lt: MAX_RETRIES }
      },
      take: 100, // Process in batches
      orderBy: { createdAt: 'asc' }
    });
  });

  if (pendingEvents.length === 0) {
    return { success: true, processed: 0 };
  }

  let processedCount = 0;

  for (const event of pendingEvents) {
    // Switch to tenant-scoped execution for processing specific events
    const tenantPrisma = withTenant(event.tenantId);

    // Optimistic locking using 'status' to prevent concurrent worker execution
    const lock = await tenantPrisma.eventOutbox.updateMany({
      where: { id: event.id, status: event.status },
      data: { status: 'PROCESSING' }
    });

    if (lock.count === 0) {
      // Event was picked up by another worker or is no longer pending/failed
      continue;
    }

    try {
      // Publish event to Inngest distributed queue
      await inngest.send({
        name: 'outbox.process',
        data: {
          jobId: event.id,
          tenantId: event.tenantId,
          actorType: 'SYSTEM',
          // Extract correlationId from strictly backend-stamped payload field to prevent spoofing, otherwise fallback to outbox ID
          correlationId: (event.payload as any)?._sys_correlationId || event.id,
          jobType: event.eventType,
          payload: event.payload,
          schemaVersion: '1.0'
        }
      });

      // Mark as PROCESSED
      await tenantPrisma.eventOutbox.update({
        where: { id: event.id },
        data: { status: 'PROCESSED', processedAt: new Date() }
      });
      processedCount++;
    } catch (errorRaw: unknown) {
      const error = errorRaw instanceof Error ? errorRaw : new Error(String(errorRaw));
      // Handle failure
      const nextRetry = new Date(Date.now() + Math.pow(2, event.retryCount) * 60000); // Exp backoff in minutes
      await tenantPrisma.eventOutbox.update({
        where: { id: event.id },
        data: {
          status: 'FAILED',
          lastError: error.message,
          retryCount: event.retryCount + 1,
          nextRetryAt: nextRetry
        }
      });
    }
  }

  return { success: true, processed: processedCount };
}

export async function cleanupOutbox() {
  Logger.info('Cleaning up EventOutbox...');

  // PROCESSED events retained for 7 days
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
  // FAILED events retained for 30 days
  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

  let deletedCount = 0;
  let hasMore = true;

  while (hasMore) {
    const deletedCountInBatch = await executeAsSystem(SystemOperation.PLATFORM_CRON, async (tx) => {
      // 1. Find candidates to delete. Using nextRetryAt as a stable timestamp for terminal failures.
      const candidates = await tx.eventOutbox.findMany({
        where: {
          OR: [
            { status: 'PROCESSED', processedAt: { lt: sevenDaysAgo } },
            { status: 'FAILED', retryCount: { gte: MAX_RETRIES }, nextRetryAt: { lt: thirtyDaysAgo } }
          ]
        },
        select: { id: true },
        take: 200 // Bound batch size
      });

      if (candidates.length === 0) {
        return 0;
      }

       
      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
      const idsToDelete = candidates.map((c: any) => c.id);

      // 2. Delete candidates using PK to avoid massive locking
      const deleteResult = await tx.eventOutbox.deleteMany({
        where: {
          id: { in: idsToDelete },
          // Double check status to prevent race conditions just in case
          status: { in: ['PROCESSED', 'FAILED'] }
        }
      });

      return deleteResult.count;
    });

    deletedCount += deletedCountInBatch;

    if (deletedCountInBatch === 0) {
      hasMore = false;
    }
  }

  Logger.info(`Outbox cleanup completed. Deleted ${deletedCount} records.`);
  return { success: true, deleted: deletedCount };
}

import { requireAuth, requireTenant, requirePermission, requireAuthIdentity, requirePermissionFast, requireTenantFromIdentity } from '@/lib/auth';
import { requireRelationOwnership } from '@/lib/auth/relation-auth';
import { withTenant, withTenantTransaction } from '@db/utils/prisma-tenant';
import { CreateCustomerInput, UpdateCustomerInput } from '../crm.types';

import { createTenantCustomerFast } from '@db/utils/fast-tenant-queries';

export async function createCustomer(input: CreateCustomerInput) {
  const startTotal = performance.now();
  Logger.info(`[PHASE_26E_MEASUREMENT] Starting createCustomer...`);
  
  const startAuth = performance.now();
  const identity = await requireAuthIdentity();
  const tenantId = await requireTenantFromIdentity(identity);
  Logger.info(`[PHASE_26E_MEASUREMENT] Auth lookup duration: ${(performance.now() - startAuth).toFixed(2)}ms`);
  
  const startParallel = performance.now();
  const normalizedName = input.name.toLowerCase().trim().replace(/\s+/g, ' ');

  await requirePermissionFast(identity.id, 'CUSTOMER', 'CREATE');

  const prismaModule = await import('@db/utils/prisma');
  const existing = await prismaModule.default.customer.findFirst({
    where: { tenantId, normalizedName, deletedAt: null },
    select: { id: true }
  });

  if (existing) throw new Error('A customer with this name already exists.');

  Logger.info(`[PHASE_26E_MEASUREMENT] Parallel checks duration: ${(performance.now() - startParallel).toFixed(2)}ms`);
  
  const startWrite = performance.now();
  const result = await createTenantCustomerFast(tenantId, identity.id, input);
  
  const serviceTimings = {
    authLookup: (startParallel - startAuth).toFixed(2),
    parallelChecks: (startWrite - startParallel).toFixed(2),
    fastTenantWrite: (performance.now() - startWrite).toFixed(2),
    totalService: (performance.now() - startTotal).toFixed(2)
  };
  
  return { 
    ...result.customer, 
    _debugTimings: { 
      ...serviceTimings, 
      ...result.timings 
    } 
  };
}

import { QueryParams, PaginatedResponse } from '../../core/types';
import globalPrisma from '@db/utils/prisma';
import { Logger } from '@/lib/logger/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export async function getCustomers(params?: QueryParams & { createdAtStart?: Date; createdAtEnd?: Date; }): Promise<PaginatedResponse<any>> {
  await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('CUSTOMER', 'READ');

  const prisma = withTenant(tenantId);
  const limit = params?.limit || 50;
  
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const where: any = { deletedAt: null, tenantId };
  
  if (params?.search) {
    where.name = { contains: params.search, mode: 'insensitive' };
  }
  
  if (params?.filters) {
    if (params.filters.industry) where.industry = params.filters.industry;
    if (params.filters.status) where.status = params.filters.status;
    if (params.filters.assignedUserId) where.assignedUserId = params.filters.assignedUserId;
  }

  if (params?.createdAtStart || params?.createdAtEnd) {
    where.createdAt = {};
    if (params.createdAtStart) where.createdAt.gte = params.createdAtStart;
    if (params.createdAtEnd) where.createdAt.lte = params.createdAtEnd;
  }

  // Allowlist sortBy to prevent dynamic key injection.
  const CUSTOMER_SORT_FIELDS = new Set(['createdAt', 'updatedAt', 'name', 'industry', 'status']);
  const safeSortBy = CUSTOMER_SORT_FIELDS.has(params?.sortBy || '') ? params!.sortBy! : 'createdAt';
  const safeSortOrder = params?.sortOrder === 'asc' ? 'asc' : 'desc';

  const customers = await prisma.customer.findMany({
    where,
    take: limit + 1,
    ...(params?.cursor ? { cursor: { id: params.cursor }, skip: 1 } : {}),
    orderBy: {
      [safeSortBy]: safeSortOrder
    }
  });

  const hasMore = customers.length > limit;
  const data = hasMore ? customers.slice(0, -1) : customers;
  const nextCursor = hasMore ? data[data.length - 1].id : null;

  return {
    data,
    pagination: {
      nextCursor,
      hasMore
    }
  };
}

export async function getCustomerById(id: string) {
  await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('CUSTOMER', 'READ');

  const prisma = withTenant(tenantId);
  
  const customer = await prisma.customer.findFirst({
    where: { id, tenantId, deletedAt: null },
    include: {
      locations: { where: { deletedAt: null }, take: 100 },
      contacts: { where: { deletedAt: null }, take: 100 },
      tasks: { where: { deletedAt: null }, orderBy: { createdAt: 'desc' }, take: 20 },
      assignedUser: { select: { id: true, email: true } },
      _count: {
        select: {
          tasks: { where: { status: { not: 'COMPLETED' }, deletedAt: null } },
          contacts: { where: { deletedAt: null } },
          locations: { where: { deletedAt: null } }
        }
      }
    }
  });

  if (!customer) return null;

  // Attempt to find related leads by company or exact name
  const relatedLeads = await prisma.lead.findMany({
    where: { tenantId, deletedAt: null, OR: [{ company: customer.name }, { email: { in: customer.contacts.map(c => c.email).filter(Boolean) as string[] } }] },
    take: 10
  });

  return { ...customer, relatedLeads };
}

export async function updateCustomer(input: UpdateCustomerInput) {
  const user = await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('CUSTOMER', 'UPDATE');


  const prisma = withTenant(tenantId);

  return await globalPrisma.$transaction(async (baseTx) => {
    const tx = await withTenantTransaction(baseTx, tenantId);
    const customer = await tx.customer.findFirst({ where: { id: input.id, tenantId }});
    if (!customer) throw new Error('Customer not found');

    let assignmentChanged = false;
    if (input.assignedUserId && input.assignedUserId !== customer.assignedUserId) {
      assignmentChanged = true;
    }

    const updated = await tx.customer.updateMany({
      where: { id: input.id, tenantId, updatedAt: customer.updatedAt },
      data: {
        name: input.name,
        industry: input.industry,
        status: input.status,
        assignedUserId: input.assignedUserId,
      }
    });

    if (updated.count === 0) {
      throw new Error('CONCURRENCY_CONFLICT: The customer was modified by another user. Please refresh and try again.');
    }

    await tx.auditLog.create({
      data: {
        tenantId,
        actorId: user.id,
        actorType: 'USER',
        action: 'CUSTOMER_UPDATED',
        resource: 'CUSTOMER',
        resourceId: input.id,
      }
    });

    await tx.activityTimeline.create({
      data: {
        tenantId,
        type: 'SYSTEM',
        content: `Customer updated`,
        actorId: user.id,
        entityType: 'CUSTOMER',
        entityId: input.id
      }
    });

    if (assignmentChanged) {
      await tx.auditLog.create({
        data: {
          tenantId,
          actorId: user.id,
          actorType: 'USER',
          action: 'CUSTOMER_ASSIGNMENT_CHANGED',
          resource: 'CUSTOMER',
          resourceId: input.id,
          metadata: { newAssignedUserId: input.assignedUserId }
        }
      });

      await tx.activityTimeline.create({
        data: {
          tenantId,
          type: 'SYSTEM',
          content: `Customer assigned to user ID: ${input.assignedUserId}`,
          actorId: user.id,
          entityType: 'CUSTOMER',
          entityId: input.id
        }
      });
    }

    return tx.customer.findFirst({ where: { id: input.id, tenantId }});
  });
}

export async function deleteCustomer(customerId: string) {
  const user = await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('CUSTOMER', 'DELETE');

  const prisma = withTenant(tenantId);

  return await globalPrisma.$transaction(async (baseTx) => {
    const tx = await withTenantTransaction(baseTx, tenantId);
    const customer = await tx.customer.findFirst({ where: { id: customerId, tenantId, deletedAt: null } });
    if (!customer) throw new Error('Customer not found');

    const now = new Date();
    await tx.customer.update({
      where: { id: customerId },
      data: { deletedAt: now }
    });
    await tx.customerContact.updateMany({
      where: { customerId, deletedAt: null },
      data: { deletedAt: now }
    });
    await tx.task.updateMany({
      where: { customerId, deletedAt: null },
      data: { deletedAt: now }
    });
    await tx.location.updateMany({
      where: { customerId, deletedAt: null },
      data: { deletedAt: now }
    });
    await tx.deal.updateMany({
      where: { customerId, deletedAt: null },
      data: { deletedAt: now }
    });
    await tx.cRMComment.updateMany({
      where: { entityType: 'CUSTOMER', entityId: customerId, deletedAt: null },
      data: { deletedAt: now }
    });

    await tx.auditLog.create({
      data: {
        tenantId,
        actorId: user.id,
        actorType: 'USER',
        action: 'CUSTOMER_DELETED',
        resource: 'CUSTOMER',
        resourceId: customerId,
      }
    });

    return { success: true };
  });
}

