import { withTenant, withTenantTransaction } from '@db/utils/prisma-tenant';
import { requireAuth, requireTenant, requirePermission } from '@/lib/auth';
import { Prisma } from '@prisma/client';
import crypto from 'crypto';
import globalPrisma from '@db/utils/prisma';

export async function getDeals(params?: {
  pipelineId?: string;
  stageId?: string;
  assignedUserId?: string;
  status?: 'OPEN' | 'WON' | 'LOST';
  search?: string;
  cursor?: string;
  limit?: number;
}) {
  const tenantId = await requireTenant();
  const prisma = withTenant(tenantId);
  await requirePermission('CUSTOMER', 'READ'); // Basic access

  const where: Prisma.DealWhereInput = {
    tenantId,
    deletedAt: null
  };

  if (params?.pipelineId) where.pipelineId = params.pipelineId;
  if (params?.stageId) where.stageId = params.stageId;
  if (params?.assignedUserId) where.assignedUserId = params.assignedUserId;
  if (params?.status) where.status = params.status;
  if (params?.search) {
    where.OR = [
      { title: { contains: params.search, mode: 'insensitive' } },
      { customer: { name: { contains: params.search, mode: 'insensitive' } } }
    ];
  }


   
  const args: Prisma.DealFindManyArgs = {
    where,
    orderBy: { createdAt: 'desc' },
    include: {
      customer: { select: { id: true, name: true } },
      assignedUser: { select: { id: true, email: true } },
      stage: { select: { id: true, name: true, probability: true, isClosedWon: true, isClosedLost: true, color: true } }
    }
  };

  if (params?.limit) {
    args.take = params.limit + 1; // fetch 1 extra to check hasMore
  }
  if (params?.cursor) {
    args.cursor = { id: params.cursor };
    args.skip = 1; // skip the cursor itself
  }

  const results = await prisma.deal.findMany(args);

  let hasMore = false;
  let data = results;
  if (params?.limit && results.length > params.limit) {
    hasMore = true;
    data = results.slice(0, params.limit);
  }

  return { data, hasMore };
}

export async function getDealById(id: string) {
  const tenantId = await requireTenant();
  const prisma = withTenant(tenantId);
  await requirePermission('CUSTOMER', 'READ');

  const deal = await prisma.deal.findFirst({
    where: { id, tenantId, deletedAt: null },
    include: {
      customer: true,
      lead: true,
      assignedUser: { select: { id: true, email: true } },
      createdUser: { select: { id: true, email: true } },
      stage: true,
      pipeline: true,
      stageHistory: {
        orderBy: { createdAt: 'desc' },
        include: {
          fromStage: { select: { name: true } },
          toStage: { select: { name: true } },
          changedBy: { select: { id: true, email: true } }
        }
      },
      tasks: {
        where: { deletedAt: null },
        orderBy: { dueDate: 'asc' }
      }
    }
  });

  if (!deal) throw new Error('Deal not found');
  return deal;
}

export async function createDeal(data: {
  title: string;
  description?: string;
  source?: string;
  value: number;
  expectedCloseDate?: Date;
  pipelineId: string;
  stageId: string;
  customerId?: string;
  assignedUserId: string;
}) {
  const user = await requireAuth();

  const tenantId = await requireTenant();
    const prisma = withTenant(tenantId);

  await requirePermission('CUSTOMER', 'CREATE');

   
  return await globalPrisma.$transaction(async (baseTx: Prisma.TransactionClient) => {
    const tx = await withTenantTransaction(baseTx, tenantId);

    // Explicit tenant boundary checks to prevent BOLA via nested foreign key assignment
    if (data.customerId) {
       const customer = await tx.customer.findFirst({ where: { id: data.customerId, tenantId } });
       if (!customer) throw new Error('Customer not found in current tenant');
    }
    const pipeline = await tx.pipeline.findFirst({ where: { id: data.pipelineId, tenantId } });
    if (!pipeline) throw new Error('Pipeline not found in current tenant');

    const stage = await tx.pipelineStage.findFirst({ where: { id: data.stageId, tenantId } });
    if (!stage) throw new Error('Stage not found in current tenant');

    const assignee = await tx.user.findFirst({ where: { id: data.assignedUserId, tenantId } });
    if (!assignee) throw new Error('Assigned user not found in current tenant');

    const deal = await tx.deal.create({
      data: {
        tenantId,
        createdById: user.id,
        title: data.title,
        description: data.description,
        source: data.source,
        value: data.value,
        expectedCloseDate: data.expectedCloseDate,
        pipelineId: data.pipelineId,
        stageId: data.stageId,
        customerId: data.customerId,
        assignedUserId: data.assignedUserId,
      },
      include: { stage: true }
    });

    // Record initial history
    await tx.dealStageHistory.create({
      data: {
        tenantId,
        dealId: deal.id,
        toStageId: data.stageId,
        changedById: user.id
      }
    });

    // Timeline
    await tx.activityTimeline.create({
      data: {
        tenantId,
        entityType: 'DEAL',
        entityId: deal.id,
        actorId: user.id,
        type: 'SYSTEM',
        content: `Deal created in stage: ${deal.stage.name}`,
      }
    });

    await tx.eventOutbox.create({
      data: {
        eventId: crypto.randomUUID(),
        tenantId,
        eventType: 'DEAL_CREATED',
        payload: { actorId: user.id, resource: 'DEAL', action: 'CREATE', metadata: { dealId: deal.id } }
      }
    });

    return deal;
  });
}

export async function convertLeadToDeal(leadId: string, assignedUserId: string, value: number, pipelineId: string, stageId: string) {
  const user = await requireAuth();
  const tenantId = await requireTenant();
  const prisma = withTenant(tenantId);
  await requirePermission('CUSTOMER', 'UPDATE');


  const lead = await prisma.lead.findFirst({ where: { id: leadId, tenantId } });
  if (!lead) throw new Error('Lead not found');

   
  return await globalPrisma.$transaction(async (baseTx: Prisma.TransactionClient) => {
    const tx = await withTenantTransaction(baseTx, tenantId);
    // Note: If customer already exists for this lead (it shouldn't normally if it's just a lead,
    // but in case conversion happened partially), we can link or create customer.
    // For simplicity, we just create the deal linked to the Lead.
    // Real CRM conversion creates Customer AND Deal.

    let customerId = undefined;
    // Find or create customer from lead
    const normalizedName = lead.name.toLowerCase().trim();
    let customer = await tx.customer.findFirst({ where: { tenantId, normalizedName, deletedAt: null } });
    if (!customer) {
      customer = await tx.customer.create({
        data: {
          tenantId,
          name: lead.name,
          normalizedName,
          assignedUserId: lead.assignedUserId || assignedUserId,
          status: 'ACTIVE'
        }
      });
    }
    customerId = customer.id;

    const deal = await tx.deal.create({
      data: {
        tenantId,
        title: `${lead.company || lead.name} Deal`,
        value,
        pipelineId,
        stageId,
        customerId,
        leadId,
        assignedUserId,
        createdById: user.id
      },
      include: { stage: true }
    });

    // Update Lead to converted
    await tx.lead.update({
      where: { id: leadId },
      data: { status: 'CONVERTED' }
    });

    // History and Timeline
    await tx.dealStageHistory.create({
      data: { tenantId, dealId: deal.id, toStageId: stageId, changedById: user.id }
    });
    await tx.activityTimeline.create({
      data: { tenantId, entityType: 'DEAL', entityId: deal.id, actorId: user.id, type: 'SYSTEM', content: `Converted from Lead` }
    });

    await tx.eventOutbox.create({
      data: {
        eventId: crypto.randomUUID(),
        tenantId,
        eventType: 'DEAL_CREATED',
        payload: { actorId: user.id, resource: 'DEAL', action: 'CREATE', metadata: { dealId: deal.id, convertedFromLeadId: leadId } }
      }
    });

    return deal;
  });
}


export async function moveDealStage(dealId: string, newStageId: string, lostReason?: string, lostCompetitor?: string, lostNotes?: string) {
  const user = await requireAuth();

  const tenantId = await requireTenant();
    const prisma = withTenant(tenantId);
  await requirePermission('CUSTOMER', 'UPDATE');

   
  return await globalPrisma.$transaction(async (baseTx: Prisma.TransactionClient) => {
    const tx = await withTenantTransaction(baseTx, tenantId);
    const deal = await tx.deal.findFirst({ where: { id: dealId, tenantId }, include: { stage: true } });
    if (!deal) throw new Error('Deal not found');

    const newStage = await tx.pipelineStage.findFirst({ where: { id: newStageId, tenantId } });
    if (!newStage) throw new Error('Stage not found');

    if (deal.stageId === newStageId) return deal;

    let status: 'OPEN' | 'WON' | 'LOST' = 'OPEN';
    let actualCloseDate: Date | null = deal.actualCloseDate;

    if (newStage.isClosedWon) {
      status = 'WON';
      actualCloseDate = new Date();
    } else if (newStage.isClosedLost) {
      status = 'LOST';
      actualCloseDate = new Date();
    }

    const updated = await tx.deal.updateMany({
      where: { id: dealId, version: deal.version },
      data: {
        stageId: newStageId,
        status,
        actualCloseDate,
        lostReason: status === 'LOST' ? lostReason : null,
        lostCompetitor: status === 'LOST' ? lostCompetitor : null,
        lostNotes: status === 'LOST' ? lostNotes : null,
        lostAt: status === 'LOST' ? new Date() : null,
        version: { increment: 1 }
      }
    });

    if (updated.count === 0) {
      throw new Error('Concurrency conflict: Deal was updated by another user');
    }

    // History & Timeline
    await tx.dealStageHistory.create({
      data: {
        tenantId,
        dealId,
        fromStageId: deal.stageId,
        toStageId: newStageId,
        changedById: user.id
      }
    });

    await tx.activityTimeline.create({
      data: {
        tenantId, entityType: 'DEAL', entityId: dealId, actorId: user.id, type: 'SYSTEM',
        content: `Moved to stage: ${newStage.name}`,
      }
    });

    await tx.eventOutbox.create({
      data: {
        eventId: crypto.randomUUID(),
        tenantId,
        eventType: 'DEAL_STAGE_CHANGED',
        payload: { actorId: user.id, resource: 'DEAL', action: 'UPDATE', metadata: { dealId, fromStageId: deal.stageId, toStageId: newStageId } }
      }
    });

    if (status === 'WON') {
      await tx.eventOutbox.create({
        data: { eventId: crypto.randomUUID(), tenantId, eventType: 'DEAL_WON', payload: { actorId: user.id, resource: 'DEAL', action: 'UPDATE', metadata: { dealId } } }
      });
    }
    if (status === 'LOST') {
      await tx.eventOutbox.create({
        data: { eventId: crypto.randomUUID(), tenantId, eventType: 'DEAL_LOST', payload: { actorId: user.id, resource: 'DEAL', action: 'UPDATE', metadata: { dealId } } }
      });
    }

    // Return the updated deal representation
    return { ...deal, stageId: newStageId, status, version: deal.version + 1 };
  });
}

export async function getDealAnalytics() {
  const tenantId = await requireTenant();
  const prisma = withTenant(tenantId);
  await requirePermission('CUSTOMER', 'READ');

  const deals = await prisma.deal.findMany({
    where: { tenantId, deletedAt: null },
    select: { value: true, probability: true, status: true, expectedCloseDate: true, stage: { select: { probability: true } } }
  });

  let totalPipelineValue = 0;
  let weightedPipelineValue = 0;
  let wonRevenue = 0;
  let lostRevenue = 0;
  let activeDealsCount = 0;
  let wonDealsCount = 0;

  const now = new Date();
  let closingThisMonth = 0;

  deals.forEach(d => {
    if (d.status === 'WON') {
      wonRevenue += d.value;
      wonDealsCount++;
    } else if (d.status === 'LOST') {
      lostRevenue += d.value;
    } else {
      totalPipelineValue += d.value;
      const p = d.probability ?? d.stage.probability;
      weightedPipelineValue += (d.value * p) / 100;
      activeDealsCount++;

      if (d.expectedCloseDate && d.expectedCloseDate.getMonth() === now.getMonth() && d.expectedCloseDate.getFullYear() === now.getFullYear()) {
        closingThisMonth++;
      }
    }
  });

  const winRate = (wonDealsCount + (deals.length - activeDealsCount > 0 ? (deals.length - activeDealsCount - wonDealsCount) : 0)) > 0
    ? (wonDealsCount / (deals.length - activeDealsCount)) * 100
    : 0;

  const averageDealSize = wonDealsCount > 0 ? wonRevenue / wonDealsCount : 0;

  return {
    totalPipelineValue,
    weightedPipelineValue,
    wonRevenue,
    lostRevenue,
    activeDealsCount,
    closingThisMonth,
    winRate: Math.round(winRate),
    averageDealSize
  };
}

export async function getDealTimeline(
  dealId: string,
  cursor?: string,
  limit: number = 50
) {
  const tenantId = await requireTenant();

  const prisma = withTenant(tenantId);
  await requirePermission('CUSTOMER', 'READ');

  const deal = await prisma.deal.findFirst({ where: { id: dealId, tenantId, deletedAt: null } });
  if (!deal) throw new Error('Deal not found');

   
  const conditions: Prisma.ActivityTimelineWhereInput[] = [{ entityType: 'DEAL', entityId: dealId }];
  if (deal.leadId) {
    conditions.push({ entityType: 'LEAD', entityId: deal.leadId });
  }

  const take = limit + 1;
  const timeline = await prisma.activityTimeline.findMany({
    where: {
      tenantId,
      OR: conditions,
      ...(cursor ? { id: { lt: cursor } } : {})
    },
    orderBy: { createdAt: 'desc' },
    take
  });

  const hasMore = timeline.length > limit;
  const events = hasMore ? timeline.slice(0, limit) : timeline;
  const nextCursor = hasMore && events.length > 0 ? events[events.length - 1].id : null;

  return { events, hasMore, nextCursor };
}


export async function updateDeal(id: string, data: {
  title?: string;
  description?: string;
  source?: string;
  value?: number;
  expectedCloseDate?: Date | null;
  pipelineId?: string;
  stageId?: string;
  customerId?: string | null;
  assignedUserId?: string;
}) {
  const user = await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('CUSTOMER', 'UPDATE');

  return await globalPrisma.$transaction(async (baseTx: Prisma.TransactionClient) => {
    const tx = await withTenantTransaction(baseTx, tenantId);

    const deal = await tx.deal.findFirst({ where: { id, tenantId, deletedAt: null } });
    if (!deal) throw new Error('Deal not found or archived');

    if (data.customerId && data.customerId !== deal.customerId) {
       const customer = await tx.customer.findFirst({ where: { id: data.customerId, tenantId } });
       if (!customer) throw new Error('Customer not found in current tenant');
    }
    if (data.pipelineId && data.pipelineId !== deal.pipelineId) {
      const pipeline = await tx.pipeline.findFirst({ where: { id: data.pipelineId, tenantId } });
      if (!pipeline) throw new Error('Pipeline not found in current tenant');
    }
    if (data.stageId && data.stageId !== deal.stageId) {
      const stage = await tx.pipelineStage.findFirst({ where: { id: data.stageId, tenantId } });
      if (!stage) throw new Error('Stage not found in current tenant');
      if (data.pipelineId && stage.pipelineId !== data.pipelineId) throw new Error('Stage does not belong to Pipeline');
      if (!data.pipelineId && stage.pipelineId !== deal.pipelineId) throw new Error('Stage does not belong to Pipeline');
    }
    if (data.assignedUserId && data.assignedUserId !== deal.assignedUserId) {
      const assignee = await tx.user.findFirst({ where: { id: data.assignedUserId, tenantId } });
      if (!assignee) throw new Error('Assigned user not found in current tenant');
    }

    const updated = await tx.deal.updateMany({
      where: { id, version: deal.version },
      data: {
        ...data,
        version: { increment: 1 }
      }
    });

    if (updated.count === 0) {
      throw new Error('Concurrency conflict: Deal was updated by another user');
    }

    await tx.activityTimeline.create({
      data: {
        tenantId,
        entityType: 'DEAL',
        entityId: id,
        actorId: user.id,
        type: 'SYSTEM',
        content: 'Deal updated',
      }
    });

    await tx.eventOutbox.create({
      data: {
        eventId: crypto.randomUUID(),
        tenantId,
        eventType: 'DEAL_UPDATED',
        payload: { actorId: user.id, resource: 'DEAL', action: 'UPDATE', metadata: { dealId: id } }
      }
    });

    return await tx.deal.findFirst({ where: { id, tenantId } });
  });
}

export async function archiveDeal(id: string) {
  const user = await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('CUSTOMER', 'UPDATE');

  return await globalPrisma.$transaction(async (baseTx: Prisma.TransactionClient) => {
    const tx = await withTenantTransaction(baseTx, tenantId);

    const deal = await tx.deal.findFirst({ where: { id, tenantId, deletedAt: null } });
    if (!deal) throw new Error('Deal not found or already archived');

    const now = new Date();

    await tx.deal.update({
      where: { id },
      data: { deletedAt: now }
    });

    await tx.task.updateMany({
      where: { dealId: id, deletedAt: null },
      data: { deletedAt: now }
    });

    await tx.cRMComment.updateMany({
      where: { entityType: 'DEAL', entityId: id, deletedAt: null },
      data: { deletedAt: now }
    });

    await tx.auditLog.create({
      data: {
        tenantId,
        actorId: user.id,
        actorType: 'USER',
        action: 'DEAL_DELETED',
        resource: 'DEAL',
        resourceId: id,
      }
    });

    return { success: true };
  });
}

import { Prisma, Lead, NotificationType } from '@prisma/client';
import { requireAuth, requireTenant, requirePermission } from '@/lib/auth';
import { withTenant, withTenantTransaction } from '@db/utils/prisma-tenant';
import { CreateLeadInput, UpdateLeadInput } from '../crm.types';
import { EventBus } from '../../core/events/event-bus';
import { NotificationService } from '../../notifications/notification.service';

export async function createLead(input: CreateLeadInput) {
  const user = await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('LEAD', 'CREATE');

  const prisma = withTenant(tenantId);

  // BUG-CRM-LEAD-001 Duplicate Prevention
  if (input.email) {
    const existing = await prisma.lead.findFirst({ where: { tenantId, email: input.email } });
    if (existing) throw new Error('A lead with this email already exists.');
  } else {
    const existing = await prisma.lead.findFirst({ where: { tenantId, name: input.name, company: input.company } });
    if (existing) throw new Error('A lead with this name and company already exists.');
  }
  // BUG-CRM-SEC-002 Cross Tenant Lead Assignment Prevention
  if (input.assignedUserId) {
    const user = await prisma.user.findFirst({ where: { id: input.assignedUserId, tenantId } });
    if (!user) throw new Error('Assigned user does not belong to this tenant.');
  }



  return await globalPrisma.$transaction(async (baseTx) => {
    const tx = await withTenantTransaction(baseTx, tenantId);
    const lead = await tx.lead.create({
      data: {
        name: input.name,
        company: input.company,
        email: input.email || null,
        phone: input.phone || null,
        assignedUserId: input.assignedUserId,
        tenantId
      }
    });

    await tx.auditLog.create({
      data: {
        tenantId,
        actorId: user.id,
        actorType: 'USER',
        action: 'LEAD_CREATED',
        resource: 'LEAD',
        resourceId: lead.id,
        metadata: { name: lead.name, company: lead.company }
      }
    });

    await tx.activityTimeline.create({
      data: {
        tenantId,
        type: 'SYSTEM',
        content: `Lead created: ${lead.name || lead.company}`,
        actorId: user.id,
        entityType: 'LEAD',
        entityId: lead.id
      }
    });

    return lead;
  });
}

import { QueryParams, PaginatedResponse } from '../../core/types';
import globalPrisma from '@db/utils/prisma';


export async function getLeads(params?: QueryParams & { createdAtStart?: Date; createdAtEnd?: Date; }): Promise<PaginatedResponse<Lead>> {
  await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('LEAD', 'READ');

  const prisma = withTenant(tenantId);

  const limit = params?.limit || 50;

    const where: Prisma.LeadWhereInput = { deletedAt: null, tenantId };

  if (params?.search) {
    where.OR = [
      { name: { contains: params.search, mode: 'insensitive' } },
      { company: { contains: params.search, mode: 'insensitive' } },
      { email: { contains: params.search, mode: 'insensitive' } }
    ];
  }

  if (params?.filters) {
    if (params.filters.status) where.status = params.filters.status;
    if (params.filters.assignedUserId) where.assignedUserId = params.filters.assignedUserId;
  }

  if (params?.createdAtStart || params?.createdAtEnd) {
    where.createdAt = {};
    if (params.createdAtStart) where.createdAt.gte = params.createdAtStart;
    if (params.createdAtEnd) where.createdAt.lte = params.createdAtEnd;
  }

  // Allowlist sortBy to prevent dynamic key injection.
  const LEAD_SORT_FIELDS = new Set(['createdAt', 'updatedAt', 'name', 'company', 'status']);
  const safeSortBy = LEAD_SORT_FIELDS.has(params?.sortBy || '') ? params!.sortBy! : 'createdAt';
  const safeSortOrder = params?.sortOrder === 'asc' ? 'asc' : 'desc';

  const leads = await prisma.lead.findMany({
    where,
    take: limit + 1,
    ...(params?.cursor ? { cursor: { id: params.cursor }, skip: 1 } : {}),
    orderBy: {
      [safeSortBy]: safeSortOrder
    }
  });

  const hasMore = leads.length > limit;
  const data = hasMore ? leads.slice(0, -1) : leads;
  const nextCursor = hasMore ? data[data.length - 1].id : null;

  return {
    data,
    pagination: {
      nextCursor,
      hasMore
    }
  };
}

export async function getLeadById(id: string) {
  await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('LEAD', 'READ');

  const prisma = withTenant(tenantId);

  const [lead, activities] = await Promise.all([
    prisma.lead.findFirst({
      where: { id, tenantId, deletedAt: null },
      include: {
        tasks: { where: { deletedAt: null }, orderBy: { createdAt: 'desc' }, take: 20 },
        deals: { where: { deletedAt: null }, orderBy: { createdAt: 'desc' }, take: 20 },
        assignedUser: { select: { id: true, email: true } },
        _count: {
          select: {
            tasks: { where: { status: { not: 'COMPLETED' }, deletedAt: null } }
          }
        }
      }
    }),
    prisma.activityTimeline.findMany({
      where: { tenantId, entityType: 'LEAD', entityId: id },
      orderBy: { createdAt: 'desc' },
      take: 20,
      include: { actor: { select: { id: true, email: true } } }
    })
  ]);

  if (!lead) return null;


  // Attempt to find a related customer by matching company name or email
  let relatedCustomer = null;
  if (lead.company || lead.email) {
        const orConditions: Prisma.CustomerWhereInput[] = [];
    if (lead.company) orConditions.push({ name: lead.company });
    if (lead.email) {
      orConditions.push({ contacts: { some: { email: lead.email, deletedAt: null } } });
    }

    if (orConditions.length > 0) {
      relatedCustomer = await prisma.customer.findFirst({
        where: { tenantId, deletedAt: null, OR: orConditions },
        select: { id: true, name: true, status: true, industry: true }
      });
    }
  }

  return { ...lead, activities, relatedCustomer };
}

export async function updateLead(input: UpdateLeadInput) {
  const user = await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('LEAD', 'UPDATE');

  const prisma = withTenant(tenantId);

  // BUG-CRM-SEC-002 Cross Tenant Lead Assignment Prevention
  if (input.assignedUserId) {

    const user = await prisma.user.findFirst({ where: { id: input.assignedUserId, tenantId } });
    if (!user) throw new Error('Assigned user does not belong to this tenant.');
  }


  const result = await globalPrisma.$transaction(async (baseTx) => {
    const tx = await withTenantTransaction(baseTx, tenantId);

    if (input.idempotencyKey) {
      // Read-before-write idempotency check (avoids aborted-transaction from catching P2002 inside $transaction)
      const existing = await tx.idempotencyKey.findUnique({
        where: { tenantId_key: { tenantId, key: input.idempotencyKey } }
      });
      if (existing) {
        // Idempotency key seen before — mutation already succeeded, return existing lead
        const existingLead = await tx.lead.findFirst({ where: { id: input.id, tenantId }, include: { assignedUser: { select: { id: true, email: true } } } });
        return { lead: existingLead, assignmentChanged: false };
      }
      // First-time: insert the key to mark this mutation as seen
      await tx.idempotencyKey.create({
        data: { tenantId, key: input.idempotencyKey, expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000) }
      });
    }

    const lead = await tx.lead.findFirst({ where: { id: input.id, tenantId }});
    if (!lead) throw new Error('Lead not found');

    let assignmentChanged = false;
    if (input.assignedUserId && input.assignedUserId !== lead.assignedUserId) {
      assignmentChanged = true;
    }

    let statusChanged = false;
    if (input.status && input.status !== lead.status) {
      statusChanged = true;
    }

    const updated = await tx.lead.updateMany({
      where: { id: input.id, tenantId, updatedAt: lead.updatedAt },
      data: {
        name: input.name,
        company: input.company,
        email: input.email === '' ? null : input.email,
        phone: input.phone === '' ? null : input.phone,
        status: input.status,
        assignedUserId: input.assignedUserId,
      }
    });

    if (updated.count === 0) {
      throw new Error('CONCURRENCY_CONFLICT: The lead was modified by another user. Please refresh and try again.');
    }

    if (assignmentChanged) {
      await tx.auditLog.create({
        data: {
          tenantId,
          actorId: user.id,
          actorType: 'USER',
          action: 'LEAD_ASSIGNMENT_CHANGED',
          resource: 'LEAD',
          resourceId: input.id,
          metadata: { newAssignedUserId: input.assignedUserId }
        }
      });
      await tx.activityTimeline.create({
        data: {
          tenantId,
          type: 'SYSTEM',
          content: `Lead assigned to user ID: ${input.assignedUserId}`,
          actorId: user.id,
          entityType: 'LEAD',
          entityId: input.id
        }
      });
    }

    if (statusChanged) {
      await tx.activityTimeline.create({
        data: {
          tenantId,
          type: 'SYSTEM',
          content: `Lead status changed from ${lead.status} to ${input.status}`,
          actorId: user.id,
          entityType: 'LEAD',
          entityId: input.id
        }
      });

      // Attempt to find user to notify (if assigned)
      if (lead.assignedUserId || input.assignedUserId) {
        await NotificationService.queueNotification(tx, {
          tenantId,
          userId: input.assignedUserId || lead.assignedUserId!,
          type: NotificationType.SYSTEM,
          title: 'Lead Status Updated',
          body: `Lead ${lead.company || lead.name} was moved to ${input.status}`,
          actionUrl: `/leads`
        });
      }
    }

    const updatedLead = await tx.lead.findFirst({ where: { id: input.id, tenantId }, include: { assignedUser: { select: { id: true, email: true } } }});
    
    if (assignmentChanged && input.assignedUserId) {
       await NotificationService.queueNotification(tx, {
          tenantId,
          userId: input.assignedUserId,
          type: NotificationType.SYSTEM,
          title: 'New Lead Assigned',
          body: 'A new lead has been assigned to you.',
          actionUrl: `/leads/${input.id}`
       });
    }

    return { lead: updatedLead, assignmentChanged };
  });

  return result.lead;
}

export async function convertLeadToCustomer(leadId: string) {

  const user = await requireAuth();
  const tenantId = await requireTenant();

  await requirePermission('LEAD', 'UPDATE');
  await requirePermission('CUSTOMER', 'CREATE');

    const prisma = withTenant(tenantId);


  return await globalPrisma.$transaction(async (baseTx) => {
    const tx = await withTenantTransaction(baseTx, tenantId);
    const lead = await tx.lead.findFirst({ where: { id: leadId, tenantId } });
    if (!lead) throw new Error('Lead not found');

    const customerName = lead.company || lead.name;
    const normalizedName = customerName.toLowerCase().trim().replace(/\s+/g, ' ');

    const customer = await tx.customer.create({
      data: {
        name: customerName,
        normalizedName,
        assignedUserId: lead.assignedUserId,
        tenantId
      }
    });

    const updateResult = await tx.lead.updateMany({
      where: { id: leadId, tenantId, updatedAt: lead.updatedAt },
      data: { status: 'CONVERTED' }
    });

    if (updateResult.count === 0) {
      throw new Error('CONCURRENCY_CONFLICT: The lead was modified by another user. Please refresh and try again.');
    }

    await tx.auditLog.create({
      data: {
        tenantId,
        actorId: user.id,
        actorType: 'USER',
        action: 'LEAD_CONVERTED',
        resource: 'LEAD',
        resourceId: leadId,
        metadata: { newCustomerId: customer.id }
      }
    });

    await tx.auditLog.create({
      data: {
        tenantId,
        actorId: user.id,
        actorType: 'USER',
        action: 'CUSTOMER_CREATED',
        resource: 'CUSTOMER',
        resourceId: customer.id,
        metadata: { source: 'LEAD_CONVERSION', leadId: leadId }
      }
    });

    await tx.activityTimeline.create({
      data: {
        tenantId,
        type: 'SYSTEM',
        content: `Lead converted to Customer`,
        actorId: user.id,
        entityType: 'LEAD',
        entityId: lead.id
      }
    });

    await tx.activityTimeline.create({
      data: {
        tenantId,
        type: 'SYSTEM',
        content: `Customer created from Lead conversion`,
        actorId: user.id,
        entityType: 'CUSTOMER',
        entityId: customer.id
      }
    });

    return customer;
  });

}


export async function deleteLead(leadId: string) {
  const user = await requireAuth();
  const tenantId = await requireTenant();
  await requirePermission('LEAD', 'DELETE');

    const prisma = withTenant(tenantId);


  return await globalPrisma.$transaction(async (baseTx) => {
    const tx = await withTenantTransaction(baseTx, tenantId);
    const lead = await tx.lead.findFirst({ where: { id: leadId, tenantId, deletedAt: null } });
    if (!lead) throw new Error('Lead not found');

    const now = new Date();
    await tx.lead.update({
      where: { id: leadId },
      data: { deletedAt: now }
    });
    await tx.task.updateMany({
      where: { leadId, deletedAt: null },
      data: { deletedAt: now }
    });
    await tx.deal.updateMany({
      where: { leadId, deletedAt: null },
      data: { deletedAt: now }
    });
    await tx.cRMComment.updateMany({
      where: { entityType: 'LEAD', entityId: leadId, deletedAt: null },
      data: { deletedAt: now }
    });

    await tx.auditLog.create({
      data: {
        tenantId,
        actorId: user.id,
        actorType: 'USER',
        action: 'LEAD_DELETED',
        resource: 'LEAD',
        resourceId: leadId,
      }
    });

    return { success: true };
  });
}

import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { withTenant } from '@db/utils/prisma-tenant';

export interface RPOMetrics {
  tenantId: string;
  rpoPolicy: string;
  targetRPOHours: number;
  currentRPOHours: number | 'INFINITE';
  lastSuccessfulBackup: Date | null;
  status: 'GREEN' | 'YELLOW' | 'RED';
}

export class RPOMonitor {
  /**
   * Calculates RPO status for all tenants.
   */
  async getGlobalRPOStatus(): Promise<RPOMetrics[]> {
    return executeAsSystem(SystemOperation.DISASTER_RECOVERY, async (tx) => {
      const tenants = await tx.tenant.findMany({
        where: { status: { not: 'DELETED' } },
        select: { id: true, rpoPolicy: true }
      });

      // PostgreSQL DISTINCT ON guarantees the first row matching the ORDER BY clause
      const latestSnapshots = await tx.recoverySnapshot.findMany({
        where: { status: 'ACTIVE' },
        orderBy: { createdAt: 'desc' },
        distinct: ['tenantId'],
        select: { id: true, tenantId: true, createdAt: true }
      });

      const snapshotMap = new Map(latestSnapshots.map((s: any) => [s.tenantId, s]));
      const metrics: RPOMetrics[] = [];
      
      for (const tenant of tenants) {
        metrics.push(this.calculateRpoSync(tenant.id, tenant.rpoPolicy, snapshotMap.get(tenant.id) || null));
      }
      return metrics;
    });
  }

  /**
   * Calculates the exact RPO metric and health status for a single tenant using a provided snapshot.
   */
  calculateRpoSync(tenantId: string, policy: string = 'BASIC', latestSnapshot: { createdAt: Date } | null): RPOMetrics {
    let targetRPOHours = 24;
    if (policy === 'BUSINESS') targetRPOHours = 12;
    if (policy === 'ENTERPRISE') targetRPOHours = 1;

    if (!latestSnapshot) {
      return {
        tenantId,
        rpoPolicy: policy,
        targetRPOHours,
        currentRPOHours: 'INFINITE',
        lastSuccessfulBackup: null,
        status: 'RED'
      };
    }

    const msSinceBackup = Date.now() - latestSnapshot.createdAt.getTime();
    const currentRPOHours = msSinceBackup / (1000 * 60 * 60);

    let status: 'GREEN' | 'YELLOW' | 'RED' = 'GREEN';
    if (currentRPOHours > targetRPOHours * 2) {
      status = 'RED'; // Severely breached
    } else if (currentRPOHours > targetRPOHours) {
      status = 'YELLOW'; // Warning, breaching
    }

    return {
      tenantId,
      rpoPolicy: policy,
      targetRPOHours,
      currentRPOHours,
      lastSuccessfulBackup: latestSnapshot.createdAt,
      status
    };
  }

  /**
   * Calculates the exact RPO metric and health status for a single tenant dynamically.
   */
  async calculateRPO(tenantId: string, policy: string = 'BASIC'): Promise<RPOMetrics> {
    const tenantPrisma = withTenant(tenantId);
    const latestSnapshot = await tenantPrisma.recoverySnapshot.findFirst({
      where: { tenantId, status: 'ACTIVE' },
      orderBy: { createdAt: 'desc' },
      select: { createdAt: true }
    });

    return this.calculateRpoSync(tenantId, policy, latestSnapshot);
  }
}

import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { withTenant } from '@db/utils/prisma-tenant';
import { getStorageProvider } from '../../../lib/storage';
import { Logger } from '@/lib/logger/logger';

 
// eslint-disable-next-line @typescript-eslint/no-unused-vars -- S2 Residual Debt: Legacy unused local
const POLICY_LIMITS: Record<string, number> = {
  DAILY: 7,
  WEEKLY: 4,
  MONTHLY: 12
};

export class RetentionPolicyService {
  /**
   * Enforces retention policies for all tenants based on their settings.
   */
  async enforceRetentionPolicies(): Promise<void> {
    const toDelete: any[] = [];
    
    // Step 1: Identify all snapshots to delete in a single bounded system transaction
    await executeAsSystem(SystemOperation.DISASTER_RECOVERY, async (tx) => {
      const tenants = await tx.tenant.findMany({
        where: { status: { not: 'DELETED' } },
        select: { id: true, rpoPolicy: true }
      });

      const allActiveSnapshots = await tx.recoverySnapshot.findMany({
        where: { status: 'ACTIVE' },
        orderBy: { createdAt: 'desc' },
        select: { id: true, tenantId: true, checksum: true }
      });

      const snapshotsByTenant = new Map<string, any[]>();
      for (const s of allActiveSnapshots) {
        if (!snapshotsByTenant.has(s.tenantId)) snapshotsByTenant.set(s.tenantId, []);
        snapshotsByTenant.get(s.tenantId)!.push(s);
      }

      for (const tenant of tenants) {
        let keepCount = 7; // Default Basic
        if (tenant.rpoPolicy === 'ENTERPRISE') keepCount = 30;
        if (tenant.rpoPolicy === 'BUSINESS') keepCount = 14;

        const snapshots = snapshotsByTenant.get(tenant.id) || [];
        if (snapshots.length > keepCount) {
          toDelete.push(...snapshots.slice(keepCount));
        }
      }
    });

    // Step 2: Perform external deletions safely outside the global transaction lock
    for (const snapshot of toDelete) {
      await this.deleteSnapshotSafely(snapshot);
    }
  }

  /**
   * Evaluates and prunes old snapshots for a single tenant manually.
   * Never deletes the most recent successful snapshot.
   */
  async enforceTenantRetention(tenantId: string): Promise<void> {
    let keepCount = 7; // Default Basic
    
    // Scoped local query for manual execution
    const toDelete = await executeAsSystem(SystemOperation.DISASTER_RECOVERY, async (tx) => {
      const tenant = await tx.tenant.findUnique({ where: { id: tenantId }, select: { rpoPolicy: true } });
      if (tenant?.rpoPolicy === 'ENTERPRISE') keepCount = 30;
      if (tenant?.rpoPolicy === 'BUSINESS') keepCount = 14;

      const snapshots = await tx.recoverySnapshot.findMany({
        where: { tenantId, status: 'ACTIVE' },
        orderBy: { createdAt: 'desc' },
        select: { id: true, tenantId: true, checksum: true }
      });

      if (snapshots.length <= keepCount) return [];
      return snapshots.slice(keepCount);
    });

    for (const snapshot of toDelete) {
      await this.deleteSnapshotSafely(snapshot);
    }
  }

  /**
   * Safely deletes a snapshot:
   * 1. Marks DELETE_PENDING atomically
   * 2. Audit record
   * 3. Deletes object storage
   * 4. Deletes DB metadata (or marks DELETED)
   // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
  async deleteSnapshotSafely(snapshot: any, isRetry = false): Promise<void> {
    const storage = getStorageProvider();
    const tenantPrisma = withTenant(snapshot.tenantId);

    // 1. Mark DELETE_PENDING atomically to avoid TOCTOU races with other retention workers
    // Prisma does not return the updated row on updateMany, but it returns the count.
    const updateResult = await tenantPrisma.recoverySnapshot.updateMany({
      where: { 
        id: snapshot.id, 
        status: isRetry ? 'DELETE_PENDING' : 'ACTIVE' 
      },
      data: { status: 'DELETE_PENDING' }
    });

    if (updateResult.count === 0 && !isRetry) {
      // Snapshot was already transitioned (e.g. by another concurrent worker)
      return;
    }

    // We need to extract the objectKey from the checksum/id, but actually we need the `RecoveryJob` that created it to get the `archiveLocation`.
    // We don't have a direct link from RecoverySnapshot -> Job right now in the schema.
    // Let's find the job by checksum.
    const job = await tenantPrisma.recoveryJob.findFirst({
      where: { tenantId: snapshot.tenantId, checksum: snapshot.checksum, status: 'COMPLETED' }
    });

    if (!job || !job.archiveLocation) {
      // If we can't find the file location, just mark it as DELETED to clean up the DB
      await tenantPrisma.recoverySnapshot.update({
        where: { id: snapshot.id },
        data: { status: 'DELETED' }
      });
      return;
     
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars -- S2 Residual Debt: Legacy unused local
    const [uri, query] = job.archiveLocation.split('?');
    let objectKey = '';
    
    if (uri.startsWith('local://')) {
      objectKey = uri.replace('local://', '').split('/')[1]; // format: local://tenantId/objectKey
    } else if (uri.startsWith('s3://')) {
      // s3://bucket/tenants/tenantId/recovery/objectKey
      const parts = uri.split('/');
      objectKey = parts[parts.length - 1];
    } else {
      // Unknown
      return;
    }

    try {
      // 3. Delete Object Storage
      const exists = await storage.verifyObjectExists(snapshot.tenantId, objectKey);
      if (exists) {
        await storage.deleteObject(snapshot.tenantId, objectKey);
      }
      
      // 4. Update DB
      await tenantPrisma.recoverySnapshot.update({
        where: { id: snapshot.id },
        data: { status: 'DELETED' }
      });

      await tenantPrisma.recoveryAuditLog.create({
        data: {
          tenantId: snapshot.tenantId,
          jobId: job.id,
          action: 'SNAPSHOT_RETENTION_DELETED',
          actorId: 'SYSTEM',
          metadata: { snapshotId: snapshot.id }
        }
      });
    } catch (eRaw: unknown) {
      const e = eRaw instanceof Error ? eRaw : new Error(String(eRaw));
      // Failsafe: leave in DELETE_PENDING, DO NOT delete database metadata.
      await tenantPrisma.recoveryAuditLog.create({
        data: {
          tenantId: snapshot.tenantId,
          jobId: job.id,
          action: 'RETENTION_DELETION_FAILED',
          actorId: 'SYSTEM',
          metadata: { snapshotId: snapshot.id, error: e.message }
        }
      });
      Logger.error('Failed to delete snapshot from storage:', e);
    }
  }

  /**
   * Resumes failed deletions (DELETE_PENDING)
   */
  async retryPendingDeletions(): Promise<void> {
    const pending = await executeAsSystem(SystemOperation.DISASTER_RECOVERY, async (tx) => tx.recoverySnapshot.findMany({
      where: { status: 'DELETE_PENDING' }
    }));

    for (const snapshot of pending) {
      await this.deleteSnapshotSafely(snapshot, true);
    }
  }
}
